svg.script:
(function () {
'use strict';
// ===================================================================
//  Core: DOM helpers, numbers, model, animation, text & math layout
// ===================================================================
const NS = 'http://www.w3.org/2000/svg';
const SVG = document.documentElement;
const C = {
  q: '#E07B24', qd: '#B85A0C', qs: '#FBE3CB',
  k: '#2F6CB3', kd: '#1F5596', ks: '#DCE7F4',
  v: '#3A8C57', vd: '#2A6E41', vs: '#DCEFE2',
  ink: '#2A2825', ink2: '#5C564C', ink3: '#948B7D', rule: '#DCD3C3',
  paper: '#FAF7F0', paper2: '#F3EDE1',
};
const RGB = { q: [224, 123, 36], k: [47, 108, 179], v: [58, 140, 87], ink: [42, 40, 37], gray: [150, 141, 128] };
const rgba = (c, a) => `rgba(${c[0]},${c[1]},${c[2]},${Math.max(0, Math.min(1, a)).toFixed(3)})`;

function el(tag, attrs, parent, text) {
  const e = document.createElementNS(NS, tag);
  if (attrs) for (const k in attrs) {
    const v = attrs[k];
    if (v === undefined || v === null || v === false) continue;
    e.setAttribute(k, v);
  }
  if (text !== undefined && text !== null) e.textContent = text;
  if (parent) parent.appendChild(e);
  return e;
}
const G = (parent, attrs) => el('g', attrs, parent);
function riseG(parent, d, attrs) {
  const g = el('g', attrs, parent);
  g.setAttribute('class', ((attrs && attrs.class) ? attrs.class + ' ' : '') + 'rise');
  g.style.setProperty('--d', (d | 0) + 'ms');
  return g;
}
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const sum = (a) => a.reduce((s, v) => s + v, 0);
const argmax = (a) => a.reduce((bi, v, i) => (v > a[bi] ? i : bi), 0);
const EASE = {
  io: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
  out: (t) => 1 - Math.pow(1 - t, 3),
  lin: (t) => t,
};
function fx(v, d = 2) {
  const a = Math.abs(v);
  let s = a >= 9.995 && d > 0 ? a.toFixed(d - 1) : a.toFixed(d);
  if (Number(s) === 0) return (0).toFixed(d);
  return (v < 0 ? '-' : '') + s;
}
const fsig = (v, d = 2) => (v >= 0 ? '+' : '-') + Math.abs(v).toFixed(d);

// ---------- seeded randomness (only for the d_k experiment) ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gaussian(rnd) {
  let spare = null;
  return () => {
    if (spare !== null) { const s = spare; spare = null; return s; }
    let u = 0; while (!u) u = rnd();
    const v = rnd(), r = Math.sqrt(-2 * Math.log(u));
    spare = r * Math.sin(2 * Math.PI * v);
    return r * Math.cos(2 * Math.PI * v);
  };
}

// ---------- linear algebra ----------
const LA = {
  mm(A, B) {
    const n = A.length, k = B.length, m = B[0].length, out = [];
    for (let i = 0; i < n; i++) {
      const r = new Array(m).fill(0);
      for (let t = 0; t < k; t++) { const a = A[i][t], b = B[t]; for (let j = 0; j < m; j++) r[j] += a * b[j]; }
      out.push(r);
    }
    return out;
  },
  T: (A) => A[0].map((_, j) => A.map((r) => r[j])),
  dot(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; },
  softmax(row) {
    const m = Math.max(...row), e = row.map((v) => Math.exp(v - m)), s = sum(e);
    return e.map((v) => v / s);
  },
  // Frobenius norm of the softmax Jacobian diag(a) - a a^T
  jacNorm(a) {
    let s = 0;
    for (let i = 0; i < a.length; i++) for (let j = 0; j < a.length; j++) {
      const v = (i === j ? a[i] : 0) - a[i] * a[j]; s += v * v;
    }
    return Math.sqrt(s);
  },
};

// ---------- the demo model ----------
// Sentence (tokenisation simplified; "The" and "the" share one vocabulary entry).
const TOK = ['The', 'animal', "didn't", 'cross', 'the', 'street', 'because', 'it', 'was', 'too', 'tired'];
const VOCAB = ['the', 'animal', "didn't", 'cross', 'street', 'because', 'it', 'was', 'too', 'tired'];
const IT = 7, ANIMAL = 1;
// Demo parameters: constructed for teaching (fitted offline to readable target patterns),
// NOT weights from the paper. Everything downstream is computed live below.
const PARAMS = {
  E: [[0.89,-0.79,0.03,-0.83,0.33,-0.35],[-0.84,-1.41,-0.9,0.11,0.67,0.95],[-0.02,-0.53,1.03,0.21,-0.42,1.07],[0.51,-1.46,1.12,0.51,0.35,-0.63],[-1.18,-0.61,-0.03,-0.75,0.19,0.21],[0.12,-0.03,0.33,0.2,0.7,0.63],[1.05,-0.09,-0.31,-1.19,-0.19,1.45],[1.01,0.14,-0.25,0.41,1.2,0.31],[0.18,0.15,0.62,-0.14,1.31,0.54],[0.9,-0.34,-0.94,0.89,-1,0.79]],
  Wq0: [[0.52,-0.12,-1.01,0.34],[-0.81,-0.01,-0.22,-0.21],[0.41,0.81,0.26,-0.18],[-0.6,-0.03,-0.1,0.08],[-0.57,0.99,-0.34,-0.36],[-0.28,-0.12,0.46,1.22]],
  Wk0: [[-0.97,-0.29,0.19,0.28],[-0.52,0.43,-0.51,-1],[-0.4,-0.22,0.86,-0.2],[-0.13,0.6,0.51,0.42],[0.59,-0.82,0.15,0.1],[-0.34,-0.56,-0.4,0.72]],
  Wq1: [[0.24,-0.6],[-0.36,-0.02],[-0.77,0.63],[0.62,0.28],[0.39,0.03],[0.3,-0.96]],
  Wk1: [[0.47,0.06],[-0.33,0.98],[0.04,0.38],[-0.59,-0.14],[0.05,-0.54],[0.85,-0.59]],
  Wq2: [[-0.78,-0.5],[-0.58,0.18],[0.54,-0.12],[0.2,-0.73],[-0.4,-0.27],[0.03,0.78]],
  Wk2: [[-0.55,0.81],[-0.94,-0.34],[0.45,0.56],[0.09,0.58],[0.13,0.3],[-0.15,0.05]],
  Wq3: [[0.45,-0.02],[-0.51,-0.32],[-0.27,-0.47],[-0.77,0.37],[-0.02,-1.09],[-0.61,-0.09]],
  Wk3: [[-0.96,0.15],[-0.34,-0.23],[-0.46,0.57],[-0.4,-0.46],[0.26,0.96],[-0.11,0.37]],
  Wv0: [[0.43,-0.23,-0.67,-0.43],[-0.68,0.76,-0.15,-0.98],[0.15,-0.78,0.99,-0.93],[1.5,0.9,-0.19,-0.65],[0.22,-0.7,-0.54,0.85],[0.62,-0.21,0.34,-0.59]],
  Wv1: [[0.74,-0.25],[-0.12,-0.51],[-0.87,-0.18],[-1.39,0.06],[-0.75,0.56],[1.18,0.29]],
  Wv2: [[0.49,0.43],[0.17,-0.26],[-0.45,0.02],[0.53,-0.97],[1.09,-0.98],[0.08,0.5]],
  Wv3: [[-0.63,-0.74],[0.23,0.53],[0.9,0.44],[-0.12,0.21],[0.34,-0.45],[-0.04,-0.55]],
  Wo: [[-0.34,-0.86,-0.16,0.23,0,-1.02],[0.38,-0.09,-0.92,-0.52,0.61,1.17],[0.51,0.36,-0.68,-0.27,1.19,-0.09],[-0.64,-0.55,-0.16,-0.62,-0.21,-0.46],[0.96,-0.09,0.69,-0.23,0.33,0.31],[0.2,0.04,-0.72,0.35,-0.33,0.22]]
};
const X0 = TOK.map((t) => PARAMS.E[VOCAB.indexOf(t.toLowerCase())].slice());
const D_MODEL = 6, D_K = 4, H = 3, D_HEAD = 2;

function attend(X, Wq, Wk, Wv, opt) {
  const o = Object.assign({ scale: true, tau: 1 }, opt);
  const Q = LA.mm(X, Wq), K = LA.mm(X, Wk), V = LA.mm(X, Wv);
  const dk = Wq[0].length;
  const c = o.scale ? 1 / Math.sqrt(dk) : 1;
  const raw = LA.mm(Q, LA.T(K));
  const S = raw.map((r) => r.map((v) => v * c));
  const A = S.map((r) => LA.softmax(r.map((v) => v / o.tau)));
  const Z = LA.mm(A, V);
  return { X, Q, K, V, raw, S, A, Z, dk, c };
}
const Model = {
  single: (opt, X) => attend(X || X0, PARAMS.Wq0, PARAMS.Wk0, PARAMS.Wv0, opt),
  head: (h, X) => attend(X || X0, PARAMS['Wq' + h], PARAMS['Wk' + h], PARAMS['Wv' + h]),
  multi() {
    const hs = [1, 2, 3].map((h) => Model.head(h));
    const concat = X0.map((_, i) => [].concat(...hs.map((r) => r.Z[i])));
    return { hs, concat, out: LA.mm(concat, PARAMS.Wo) };
  },
};

// ---------- animation ----------
let FLUSH = false;
const Anim = {
  list: new Set(), raf: 0,
  add(a) { this.list.add(a); if (!this.raf) this.raf = requestAnimationFrame(Anim.tick); },
  tick(now) {
    Anim.raf = 0;
    for (const a of Array.from(Anim.list)) {
      if (a.t0 === null) a.t0 = now;
      const p = a.dur > 0 ? clamp((now - a.t0) / a.dur, 0, 1) : 1;
      a.fn(a.ease(p));
      if (p >= 1) { Anim.list.delete(a); if (a.done) a.done(); }
    }
    if (Anim.list.size) Anim.raf = requestAnimationFrame(Anim.tick);
  },
};
function tween(dur, fn, ease, done) {
  const a = { t0: null, dur, fn, ease: ease || EASE.io, done, fin: false };
  if (FLUSH || dur <= 0) { fn(1); a.fin = true; if (done) done(); return a; }
  fn(a.ease(0));
  Anim.add(a);
  return a;
}
class Timeline {
  constructor() { this.pending = []; this.tweens = new Set(); this.loops = new Set(); this.dead = false; }
  at(ms, fn) {
    if (this.dead) return;
    if (FLUSH) { fn(); return; }
    const item = { fn, due: performance.now() + ms, id: 0 };
    item.id = setTimeout(() => {
      const i = this.pending.indexOf(item); if (i >= 0) this.pending.splice(i, 1);
      if (!this.dead) fn();
    }, ms);
    this.pending.push(item);
  }
  tween(dur, fn, ease, done) {
    if (this.dead) return null;
    let a;
    a = tween(dur, fn, ease, () => { this.tweens.delete(a); if (done) done(); });
    if (!a.fin) this.tweens.add(a);
    return a;
  }
  // endless rAF loop (decorations); killed with the timeline, skipped while flushing
  loop(fn) {
    if (this.dead) return;
    const L = { alive: true, t0: null };
    const step = (now) => {
      if (!L.alive || this.dead) return;
      if (L.t0 === null) L.t0 = now;
      fn(now - L.t0);
      requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
    this.loops.add(L);
  }
  kill() {
    this.dead = true;
    for (const p of this.pending) clearTimeout(p.id);
    this.pending = [];
    for (const a of this.tweens) Anim.list.delete(a);
    this.tweens.clear();
    for (const L of this.loops) L.alive = false;
  }
  flush() {
    FLUSH = true;
    try {
      let guard = 0;
      while ((this.pending.length || this.tweens.size) && guard++ < 200) {
        for (const a of Array.from(this.tweens)) {
          Anim.list.delete(a); this.tweens.delete(a); a.fn(1); if (a.done) a.done();
        }
        const items = this.pending.sort((a, b) => a.due - b.due);
        this.pending = [];
        for (const it of items) { clearTimeout(it.id); if (!this.dead) it.fn(); }
      }
    } finally { FLUSH = false; }
  }
}

// ---------- text measurement ----------
const measureLayer = el('g', { opacity: 0, 'aria-hidden': 'true', 'pointer-events': 'none' }, SVG);
const measurer = el('text', { x: 0, y: -200 }, measureLayer);
const mCache = new Map();
function measure(str, cls, size, weight) {
  const key = cls + '|' + size + '|' + (weight || '') + '|' + str;
  let w = mCache.get(key);
  if (w !== undefined) return w;
  measurer.setAttribute('class', cls);
  measurer.setAttribute('font-size', size);
  if (weight) measurer.setAttribute('font-weight', weight); else measurer.removeAttribute('font-weight');
  measurer.textContent = str;
  w = measurer.getComputedTextLength();
  mCache.set(key, w);
  return w;
}
const spaceW = (cls, size) => Math.max(size * 0.22, measure('a a', cls, size) - measure('aa', cls, size));

// ---------- mini TeX: parse ----------
function opAtom(c) {
  if (c === '-') c = '−';
  const rel = '=≈→<>≤≥'.includes(c), bin = '+−×·'.includes(c), punct = c === ',';
  return { t: 'atom', s: c, f: 'mo', sp: rel ? 'rel' : bin ? 'bin' : punct ? 'punct' : null };
}
function parseTex(src) {
  let i = 0;
  function row(stop) {
    const items = [];
    while (i < src.length) {
      const c = src[i];
      if (c === stop) { i++; break; }
      if (c === ' ') { i++; continue; }
      if (c === '{') { i++; items.push(row('}')); continue; }
      if (c === '_' || c === '^') {
        i++;
        const arg = argument();
        let last = items.pop() || { t: 'atom', s: '', f: 'mo' };
        if (last.t !== 'scr') last = { t: 'scr', base: last, sub: null, sup: null };
        if (c === '_') last.sub = arg; else last.sup = arg;
        items.push(last);
        continue;
      }
      if (c === '\\') { items.push(command()); continue; }
      if (/[A-Za-z]/.test(c)) {
        let w = '';
        while (i < src.length && /[A-Za-z]/.test(src[i])) w += src[i++];
        if (w.length > 1 && /[a-z]/.test(w)) items.push({ t: 'atom', s: w, f: 'mw' });
        else for (const ch of w) items.push({ t: 'atom', s: ch, f: 'mi' });
        continue;
      }
      if (/[0-9.]/.test(c)) {
        let w = '';
        while (i < src.length && /[0-9.]/.test(src[i])) w += src[i++];
        items.push({ t: 'atom', s: w, f: 'mn' });
        continue;
      }
      i++;
      items.push(opAtom(c));
    }
    return { t: 'row', items };
  }
  function argument() {
    while (src[i] === ' ') i++;
    const c = src[i];
    if (c === '{') { i++; return row('}'); }
    if (c === '\\') return command();
    i++;
    if (/[A-Za-z]/.test(c)) return { t: 'atom', s: c, f: 'mi' };
    if (/[0-9]/.test(c)) return { t: 'atom', s: c, f: 'mn' };
    return opAtom(c);
  }
  function command() {
    i++;
    let name = '';
    while (i < src.length && /[A-Za-z]/.test(src[i])) name += src[i++];
    if (!name) name = src[i++];
    switch (name) {
      case 'frac': { const num = argument(), den = argument(); return { t: 'frac', num, den }; }
      case 'sqrt': return { t: 'sqrt', body: argument() };
      case 'big': return { t: 'big', body: argument() };
      case 'q': case 'k': case 'v': case 'g': return { t: 'color', cls: 'c' + name, body: argument() };
      case 'rm': { const a = argument(); return upright(a); }
      case 'txt': { const a = argument(); return { t: 'text', s: flat(a) }; }
      case 'cdot': return opAtom('·');
      case 'times': return opAtom('×');
      case 'to': return opAtom('→');
      case 'approx': return opAtom('≈');
      case 'dots': return { t: 'atom', s: '…', f: 'mo' };
      case 'sum': return { t: 'atom', s: 'Σ', f: 'mo', big: true };
      case 'norm': return { t: 'atom', s: '‖', f: 'mo' };
      case 'partial': return { t: 'atom', s: '∂', f: 'mi' };
      case 'tau': return { t: 'atom', s: 'τ', f: 'mi' };
      case 'sigma': return { t: 'atom', s: 'σ', f: 'mi' };
      case 'pi': return { t: 'atom', s: 'π', f: 'mi' };
      case ',': return { t: 'space', em: 0.17 };
      case ';': return { t: 'space', em: 0.3 };
      case 'quad': return { t: 'space', em: 1 };
      default: return { t: 'atom', s: name, f: 'mw' };
    }
  }
  function flat(n) { return n.t === 'row' ? n.items.map(flat).join('') : (n.s || ''); }
  function upright(n) {
    if (n.t === 'row') { n.items.forEach(upright); return n; }
    if (n.t === 'atom' && n.f === 'mi') n.f = 'mw';
    return n;
  }
  return row(null);
}

// ---------- mini TeX: layout -> boxes that emit <tspan>s and paths ----------
function mlay(node, size) {
  switch (node.t) {
    case 'row': {
      const boxes = [];
      let prev = null;
      for (const it of node.items) {
        const b = mlay(it, size);
        let gapL = 0;
        if (it.t === 'atom' && it.sp) {
          const unary = !prev || (prev.t === 'atom' && (prev.sp || '(['.includes(prev.s)));
          if (it.sp === 'rel') gapL = size * 0.28;
          else if (it.sp === 'bin' && !unary) gapL = size * 0.2;
          b.gapR = it.sp === 'rel' ? size * 0.28 : it.sp === 'bin' && !unary ? size * 0.2 : it.sp === 'punct' ? size * 0.26 : 0;
        }
        b.gapL = gapL;
        boxes.push(b);
        prev = it;
      }
      let w = 0, a = size * 0.7, d = size * 0.2;
      const xs = [];
      boxes.forEach((b, k) => {
        w += b.gapL + (k > 0 ? boxes[k - 1].gapR || 0 : 0);
        xs.push(w);
        w += b.w;
        a = Math.max(a, b.a); d = Math.max(d, b.d);
      });
      return { w, a, d, emit(t, g, x, y, cc) { boxes.forEach((b, k) => b.emit(t, g, x + xs[k], y, cc)); } };
    }
    case 'atom': {
      const cls = node.f === 'mi' ? 'mi' : node.f === 'mn' ? 'mn' : node.f === 'mw' ? 'mw' : 'mo';
      const sz = node.big ? size * 1.25 : size;
      const w = measure(node.s, cls, sz) + (node.f === 'mi' ? size * 0.03 : 0);
      return {
        w, a: sz * 0.72, d: sz * 0.22,
        emit(t, g, x, y, cc) {
          el('tspan', { x: x.toFixed(2), y: (y + (node.big ? size * 0.08 : 0)).toFixed(2), class: cls + (cc ? ' ' + cc : ''), 'font-size': sz.toFixed(2) }, t, node.s);
        },
      };
    }
    case 'text': {
      const w = measure(node.s, 'sans', size * 0.8);
      return { w, a: size * 0.7, d: size * 0.2, emit(t, g, x, y, cc) { el('tspan', { x: x.toFixed(2), y: y.toFixed(2), class: 'sans' + (cc ? ' ' + cc : ''), 'font-size': (size * 0.8).toFixed(2) }, t, node.s); } };
    }
    case 'space': return { w: size * node.em, a: 0, d: 0, emit() {} };
    case 'color': {
      const b = mlay(node.body, size);
      return { w: b.w, a: b.a, d: b.d, emit(t, g, x, y) { b.emit(t, g, x, y, node.cls); } };
    }
    case 'scr': {
      const b = mlay(node.base, size);
      const ss = Math.max(size * 0.68, 9);
      const sub = node.sub && mlay(node.sub, ss), sup = node.sup && mlay(node.sup, ss);
      const ital = node.base.t === 'atom' && node.base.f === 'mi';
      const tall = node.base.t !== 'atom';
      const supX = b.w + (ital ? size * 0.04 : size * 0.02);
      const subX = b.w + (ital ? -size * 0.03 : size * 0.02);
      const supDy = tall ? -(b.a - ss * 0.3) : -size * (sub ? 0.42 : 0.38);
      const subDy = size * (sup ? 0.3 : 0.24) + (tall ? b.d * 0.5 : 0);
      const w = Math.max(sup ? supX + sup.w : b.w, sub ? subX + sub.w : b.w) + size * 0.04;
      const a = Math.max(b.a, sup ? -supDy + sup.a : 0), d = Math.max(b.d, sub ? subDy + sub.d : 0);
      return {
        w, a, d,
        emit(t, g, x, y, cc) {
          b.emit(t, g, x, y, cc);
          if (sup) sup.emit(t, g, x + supX, y + supDy, cc);
          if (sub) sub.emit(t, g, x + subX, y + subDy, cc);
        },
      };
    }
    case 'frac': {
      const s2 = size * 0.9;
      const nb = mlay(node.num, s2), db = mlay(node.den, s2);
      const pad = size * 0.14, axis = size * 0.28, gap = size * 0.14, th = Math.max(1.1, size * 0.05);
      const w = Math.max(nb.w, db.w) + 2 * pad;
      const numBase = -(axis + gap + nb.d + th / 2), denBase = -axis + gap + db.a + th / 2;
      return {
        w, a: -numBase + nb.a, d: denBase + db.d,
        emit(t, g, x, y, cc) {
          nb.emit(t, g, x + (w - nb.w) / 2, y + numBase, cc);
          db.emit(t, g, x + (w - db.w) / 2, y + denBase, cc);
          el('line', { x1: x + pad * 0.3, x2: x + w - pad * 0.3, y1: y - axis, y2: y - axis, class: 'mline', 'stroke-width': th }, g);
        },
      };
    }
    case 'sqrt': {
      const bb = mlay(node.body, size), s = size;
      const top = bb.a + s * 0.12, lw = Math.max(1.1, s * 0.055), signW = s * 0.56;
      return {
        w: signW + bb.w + s * 0.1, a: top + lw, d: bb.d + s * 0.05,
