    x, y, 'font-size': o.size || 14, class: o.cls || 'sans', 'text-anchor': o.anchor || 'start',
    'font-weight': o.weight, fill: o.fill, transform: o.rot ? `rotate(${o.rot},${x},${y})` : null,
  }, parent, str);
