// ===================================================================
//  Components: matrix, attention fan, slider, toggle, button
// ===================================================================
function cellStyle(kind, v, vmax) {
  const t = clamp(Math.abs(v) / (vmax || 1), 0, 1);
  switch (kind) {
    case 'a': return [rgba(RGB.ink, 0.035 + 0.9 * v), v > 0.5 ? C.paper : C.ink];
    case 's': return v >= 0 ? [rgba(RGB.ink, 0.05 + 0.64 * t), t > 0.6 ? C.paper : C.ink] : [rgba(RGB.gray, 0.05 + 0.24 * t), C.ink2];
    case 'x': return [rgba(RGB.gray, 0.07 + 0.3 * t), C.ink];
    case 'q': case 'k': case 'v':
