}

function Matrix(parent, o) {
  const cw = o.cw, ch = o.ch, gap = o.gap == null ? 2 : o.gap, fs = o.fs || 12;
  const m = { o, cells: [], data: null, x: o.x, y: o.y, w: o.cols * cw, h: o.rows * ch };
  m.g = el('g', { class: 'mat' + (o.onCell ? ' hot' : ''), transform: `translate(${o.x},${o.y})` }, parent);
  if (o.bracket !== false) {
    const b = 5, W = m.w, Hh = m.h;
    el('path', { d: `M${-4 + b},-4 H-4 V${Hh + 4} H${-4 + b}`, class: 'brk' }, m.g);
    el('path', { d: `M${W + 4 - b},-4 H${W + 4} V${Hh + 4} H${W + 4 - b}`, class: 'brk' }, m.g);
  }
  for (let i = 0; i < o.rows; i++) {
    const row = [];
    for (let j = 0; j < o.cols; j++) {
      const cg = el('g', { class: 'cell' }, m.g);
      const r = el('rect', {
        x: j * cw + gap / 2, y: i * ch + gap / 2, width: cw - gap, height: ch - gap,
        rx: Math.min(4.5, (ch - gap) * 0.24), fill: C.paper2,
      }, cg);
      const t = o.numbers === false ? null
        : el('text', { x: j * cw + cw / 2, y: i * ch + ch / 2 + fs * 0.36, 'text-anchor': 'middle', class: 'mono cell-t', 'font-size': fs }, cg);
      if (o.onCell) {
        cg.addEventListener('pointerenter', () => o.onCell(i, j, false));
        cg.addEventListener('click', () => o.onCell(i, j, true));
      }
      row.push({ g: cg, r, t });
    }
    m.cells.push(row);
  }
  if (o.rowLabels) {
    m.rowLab = o.rowLabels.map((s, i) => {
      const t = label(m.g, -9, i * ch + ch / 2 + (o.lfs || 14) * 0.34, s, { size: o.lfs || 14, cls: 'tok-t ink2', anchor: 'end' });
      if (o.onRow) { t.setAttribute('class', 'tok-t ink2 clickable'); t.addEventListener('click', () => o.onRow(i)); }
      return t;
    });
  }
  if (o.colLabels) {
    m.colLab = o.colLabels.map((s, j) => label(m.g, j * cw + cw / 2 - 1, -9, s, { size: o.lfs || 13, cls: 'tok-t ink2', rot: -45 }));
  }
