      const v = data[i][j], c = m.cells[i][j];
      const [fill, tf] = cellStyle(o.kind, v, vm);
      c.r.setAttribute('fill', fill);
      if (c.t) { c.t.textContent = o.fmt ? o.fmt(v) : fx(v); c.t.setAttribute('fill', tf); }
    }
  };
  m.center = (i, j) => [o.x + j * cw + cw / 2, o.y + i * ch + ch / 2];
  m.mark = (key, i0, j0, i1, j1, cls) => {
    let r = markEls[key];
    if (!r) r = markEls[key] = el('rect', { class: 'mark ' + (cls || ''), rx: 5 }, m.marks);
    r.setAttribute('class', 'mark ' + (cls || ''));
    r.setAttribute('x', j0 * cw - 1.5); r.setAttribute('y', i0 * ch - 1.5);
    r.setAttribute('width', (j1 - j0 + 1) * cw + 3); r.setAttribute('height', (i1 - i0 + 1) * ch + 3);
    r.style.display = '';
  };
  m.unmark = (key) => { if (markEls[key]) markEls[key].style.display = 'none'; };
  m.unmarkAll = () => { for (const k in markEls) markEls[k].style.display = 'none'; };
  m.hideAll = () => m.cells.flat().forEach((c) => { c.g.classList.remove('pop'); c.g.classList.add('hid'); });
  m.showAll = () => m.cells.flat().forEach((c) => c.g.classList.remove('hid'));
  m.showCell = (i, j, pop) => {
    const c = m.cells[i][j];
    if (!c.g.classList.contains('hid')) return;
