    const items = [];
    for (let i = 0; i < o.rows; i++) for (let j = 0; j < o.cols; j++) items.push([order(i, j), i, j]);
    items.sort((a, b) => a[0] - b[0]);
    let k = 0;
    tl.at(delay || 0, () => tl.tween(dur, (p) => {
      const lim = p * items.length;
      while (k < items.length && k < lim) { const it = items[k++]; m.showCell(it[1], it[2], true); }
    }, EASE.lin));
  };
  return m;
}

// Two-row attention diagram (like the paper's attention visualisations):
// top row = the querying word, bottom row = every word it can attend to.
let fanCount = 0;
function Fan(parent, o) {
  const f = { o, sel: o.sel == null ? IT : o.sel, cur: null };
  const g = el('g', { class: 'fan' }, parent);
  const gid = 'fanGrad' + (++fanCount);
  const lg = el('linearGradient', { id: gid, gradientUnits: 'userSpaceOnUse', x1: 0, y1: o.yTop, x2: 0, y2: o.yBot }, el('defs', null, g));
  el('stop', { offset: '0', 'stop-color': C.q }, lg);
  el('stop', { offset: '1', 'stop-color': C.k }, lg);
  const gl = el('g', null, g);
  let size = o.size || 24;
  let ws = TOK.map((t) => measure(t, 'tok-t', size));
  let gap = (o.x1 - o.x0 - sum(ws)) / (TOK.length - 1);
  while (gap < 18 && size > 12) { size--; ws = TOK.map((t) => measure(t, 'tok-t', size)); gap = (o.x1 - o.x0 - sum(ws)) / (TOK.length - 1); }
  const cx = [];
  let x = o.x0;
  ws.forEach((w) => { cx.push(x + w / 2); x += w + gap; });
  f.cx = cx; f.size = size; f.g = g;
  const lines = TOK.map(() => el('path', { class: 'fan-line', stroke: `url(#${gid})` }, gl));
  f.lines = lines;
  f.top = TOK.map((t, i) => {
    const tg = el('g', { class: 'tok', transform: `translate(${cx[i].toFixed(1)},${o.yTop})` }, g);
    el('rect', { class: 'pill', x: -ws[i] / 2 - 9, y: -size * 0.98, width: ws[i] + 18, height: size * 1.42, rx: size * 0.42 }, tg);
    el('text', { class: 'tok-t', 'text-anchor': 'middle', 'font-size': size }, tg, t);
    tg.addEventListener('click', () => { if (o.onPick) o.onPick(i); else f.select(i); });
    return tg;
  });
  f.bot = TOK.map((t, i) => {
    const tg = el('g', { class: 'keytok', transform: `translate(${cx[i].toFixed(1)},${o.yBot})` }, g);
    const pill = el('rect', { class: 'pill', x: -ws[i] / 2 - 9, y: -size * 0.98, width: ws[i] + 18, height: size * 1.42, rx: size * 0.42, fill: 'transparent' }, tg);
    el('text', { class: 'tok-t', 'text-anchor': 'middle', 'font-size': size }, tg, t);
    const num = o.nums === false ? null : el('text', { class: 'mono wlab', 'text-anchor': 'middle', 'font-size': o.numSize || 15, y: size * 0.44 + (o.numGap || 24) }, tg, '');
    return { g: tg, pill, num };
  });
  f.y1 = o.yTop + size * 0.5;
  f.y2 = o.yBot - size * 1.05;
  f.render = (sx, w) => {
    const y1 = f.y1, y2 = f.y2, ym = (y1 + y2) / 2;
    const order = w.map((_, j) => j).sort((a, b) => w[a] - w[b]);
    const mx = argmax(w);
    order.forEach((j) => {
      const p = lines[j];
      p.setAttribute('d', `M${sx.toFixed(1)},${y1} C${sx.toFixed(1)},${ym} ${cx[j].toFixed(1)},${ym} ${cx[j].toFixed(1)},${y2}`);
      p.setAttribute('stroke-width', (0.8 + 17 * w[j]).toFixed(2));
      p.setAttribute('stroke-opacity', (0.1 + 0.9 * Math.min(1, w[j] * 1.2)).toFixed(3));
