  el('line', { class: 'sl-track', x1: 0, x2: o.w, y1: 0, y2: 0 }, g);
  const fill = el('line', { class: 'sl-fill', x1: 0, x2: 0, y1: 0, y2: 0 }, g);
  if (o.steps) o.steps.forEach((v, k) => {
    const tx = (k / (o.steps.length - 1)) * o.w;
    el('line', { x1: tx, x2: tx, y1: 8, y2: 12, class: 'axis' }, g);
    label(g, tx, 27, String(v), { size: 11.5, cls: 'mono ink3', anchor: 'middle' });
  });
  if (o.ticks) o.ticks.forEach(([v, txt]) => {
    const tx = toT(v) * o.w;
    el('line', { x1: tx, x2: tx, y1: 8, y2: 12, class: 'axis' }, g);
    label(g, tx, 27, txt, { size: 11.5, cls: 'mono ink3', anchor: 'middle' });
  });
