  const hit = el('rect', { x: -14, y: -16, width: o.w + 28, height: 32, fill: 'transparent' }, g);
  if (o.label) para(g, o.label, { x: 0, y: -17, size: 14, cls: 'sans ink2' });
  const val = label(g, o.w, -17, '', { size: 14, cls: 'mono', anchor: 'end', weight: 700 });
  function toT(v) {
    if (o.steps) return o.steps.indexOf(v) / (o.steps.length - 1);
