  hit.addEventListener('pointercancel', () => { drag = false; });
  s.nudge = (dir) => {
    if (o.steps) s.set(o.steps[clamp(o.steps.indexOf(s.v) + dir, 0, o.steps.length - 1)], true);
    else s.set(fromT(toT(s.v) + dir * (o.nudge || 0.05)), true);
  };
  s.g = g;
  s.set(o.value, false);
  return s;
}

function Toggle(parent, o) {
  const t = { v: !!o.value };
  const g = el('g', { class: 'toggle', transform: `translate(${o.x},${o.y})` }, parent);
  el('rect', { class: 'tr', x: 0, y: -12, width: 44, height: 24, rx: 12 }, g);
  el('circle', { class: 'kn', cx: 12, cy: 0, r: 9 }, g);
  const p = para(g, o.label, { x: 54, y: 5.5, size: o.size || 15, cls: 'sans' });
  const st = label(g, 54 + p.w + 8, 5.5, '', { size: 13, cls: 'sans ink3' });
  el('rect', { x: -4, y: -16, width: 54 + p.w + 44, height: 32, fill: 'transparent' }, g);
  g.addEventListener('click', () => { userAct(); t.set(!t.v, true); });
  t.set = (v, fire) => {
    t.v = v; g.classList.toggle('on', v);
    st.textContent = v ? (o.on || '开') : (o.off || '关');
    if (fire && o.onChange) o.onChange(v);
  };
  t.g = g;
  t.w = 54 + p.w + 40;
  t.set(t.v);
  return t;
}

function Button(parent, o) {
  const size = o.size || 15, h = o.h || 36;
  const w = o.w || Math.ceil(measure(o.label, 'sans', size, 600) + (o.pad || 34));
  const g = el('g', { class: 'btn ' + (o.kind || ''), transform: `translate(${o.x},${o.y})`, role: 'button' }, parent);
  el('rect', { x: 0, y: 0, width: w, height: h, rx: o.rx == null ? h / 2 : o.rx }, g);
  const t = el('text', { x: w / 2, y: h / 2 + size * 0.36, 'text-anchor': 'middle', 'font-size': size, class: 'sans' }, g, o.label);
  g.addEventListener('click', (e) => { e.stopPropagation(); if (o.onClick) o.onClick(); });
  return {
    g, w, h,
    setLabel: (s) => { t.textContent = s; },
    setOn: (v) => g.classList.toggle('on', !!v),
    setDisabled: (v) => g.classList.toggle('dis', !!v),
  };
}

// small helpers for diagrams
function arrow(parent, d, o) {
  o = o || {};
  return el('path', { d, fill: 'none', stroke: o.stroke || C.ink2, 'stroke-width': o.w || 1.4, 'marker-end': o.marker === false ? null : `url(#${o.marker || 'arr'})`, 'stroke-dasharray': o.dash, opacity: o.opacity }, parent);
}
function box(parent, x, y, w, h, o) {
  o = o || {};
  return el('rect', { x, y, width: w, height: h, rx: o.rx == null ? 7 : o.rx, fill: o.fill || C.paper2, stroke: o.stroke || C.ink2, 'stroke-width': o.sw || 1.2, 'stroke-dasharray': o.dash }, parent);
}

