    box(boxes, (o && o.x) || bx, y, (o && o.w) || bw, 40, { rx: 8, fill: (o && o.fill) || C.paper2, stroke: C.ink2, dash: o && o.dash });
    label(boxes, (o && o.c) || cx, y + 26, txt, { size: 16, anchor: 'middle', weight: 600, cls: 'sans' });
  };
