  B(556, 'Mask (opt.)', { dash: '5 4', fill: C.paper });
  B(476, 'SoftMax');
  B(396, 'MatMul', { x: m2x, w: m2w, c: m2c });
  formula(g, '\\q{Q}', { x: xq, y: 836, size: 30, anchor: 'middle' });
  formula(g, '\\k{K}', { x: xk, y: 836, size: 30, anchor: 'middle' });
  formula(g, '\\v{V}', { x: xv, y: 836, size: 30, anchor: 'middle' });
  formula(g, 'Attention(\\q{Q}, \\k{K}, \\v{V})', { x: m2c, y: 330, size: 21, anchor: 'middle' });
  const A = (y, s) => para(ann, s, { x: 1244, y: y + 25, size: 13.5, cls: 'sans ink3' });
  A(716, '{m:\\q{Q}\\k{K}^T}：两两打分');
  A(636, '÷ {m:\\sqrt{d_k}}');
  A(556, '可选（解码器）');
  A(476, '每行和为 1');
  para(ann, '× {m:\\v{V}}：加权求和', { x: 1412, y: 421, size: 13.5, cls: 'sans ink3' });
  label(g, 1210, 884, '缩放点积注意力（按论文图 2 左重绘）', { size: 14, cls: 'sans ink3', anchor: 'middle' });
  // flowing dots (SMIL, decorative)
  const dot = (color, path, begin) => {
    const c = el('circle', { r: 5.5, fill: color, class: 'flowdot', opacity: 0.9 }, flow);
    el('animateMotion', { dur: '3.6s', repeatCount: 'indefinite', path, begin }, c);
  };
  dot(C.q, `M${xq},806 V736 H${cx} V416 H${m2c} V330`, '0s');
  dot(C.k, `M${xk},806 V736 H${cx} V416 H${m2c} V330`, '0.35s');
  dot(C.v, `M${xv},806 V416 H${m2c} V330`, '1.1s');
}
