    para(L, '② {b:难以并行}：{m:h_t} 必须等 {m:h_{t-1}}，同一个句子内部只能顺序计算；句子越长，这个瓶颈越明显（论文 §1）。', { x: 72, y: 530 + p1.h + 16, w: 650, size: 17, lh: 28 });
