    });
    para(R, '{m:n}：序列长度　{m:d}：表示维度　{m:k}：卷积核大小', { x: 800, y: 728, size: 13.5, cls: 'sans ink3' });
    para(R, '→ 自注意力让任意两个位置直接相连：路径长度 {m:O(1)}，一层之内所有位置同时计算。下一步看它是怎么做到的。', { x: 800, y: 790, w: 728, size: 17, lh: 28 });
  },
  enter(tl) {
    const N = TOK.length, per = 430, hold = 2600, period = N * per + hold;
    const setT = (t) => {
      this.cells.forEach((c, i) => { c.classList.toggle('act', i === t); c.classList.toggle('done', i < t); });
      this.seq.forEach((r, i) => r.setAttribute('fill', i < t ? '#D8CFBF' : i === t ? C.ink : C.paper2));
      this.par.forEach((r) => r.setAttribute('fill', t >= 0 ? C.ink : C.paper2));
      this.counter.textContent = t >= 0 ? `顺序计算：第 ${Math.min(t + 1, N)} / ${N} 步` : '';
      const hop = clamp(t - 1, 0, 6);
      const on = t >= 1;
      const x = this.cx[1 + hop];
      this.dot.setAttribute('cx', x);
