      this.dotLab.setAttribute('x', x + 14);
      this.dotLab.setAttribute('opacity', on && hop === 0 ? 1 : 0);
      this.bracket.setAttribute('opacity', t >= 7 ? 1 : 0);
    };
    setT(-1);
    let last = -2;
    tl.at(700, () => tl.loop((ms) => {
      const ph = ms % period;
      const t = ph < N * per ? Math.floor(ph / per) : N - 1;
      if (t !== last) { last = t; setT(t); }
    }));
    this.freeze = () => setT(N - 1);
  },
  dwell: 9000,
});

// ---------------------------------------------------------------- step 2
SC.push({
  kicker: 'STEP 2 · 论文 §3.2', short: '关键想法',
  title: '关键想法：每个词直接看向所有词',
  lead: '让一个词和句子里的所有词（包括它自己）各算一个相关度，把相关度变成加起来等于 1 的权重，再按权重把大家的信息加权汇总——这就是注意力（attention）。',
  leadW: 1456,
  keys: '↑↓ 换词',
  build(g) {
    header(g, this);
