      x0: 236, x1: 1492, yTop: 252, yBot: 420, size: 24, numGap: 25,
      getW: (i) => att.A[i],
      onPick: (i) => { userAct(); hint.style.display = 'none'; this.select(i); },
      onRender: (w) => this.renderPipe(w),
    });
    // pipeline rows under the fan, aligned with the word columns
    const P = riseG(g, 300);
    const pl = (y, s) => para(P, s, { x: 208, y, size: 14, cls: 'sans ink3', anchor: 'end' });
    pl(514, '① 相关度分数'); pl(582, '② softmax'); pl(642, '③ 权重 × value');
    this.scoreT = fan.cx.map((x) => label(P, x, 514, '', { size: 14, cls: 'mono ink2', anchor: 'middle' }));
    el('line', { x1: 236, x2: 1492, y1: 600.5, y2: 600.5, class: 'axis' }, P);
    this.bars = fan.cx.map((x) => el('rect', { x: x - 13, y: 600, width: 26, height: 0, rx: 3, fill: C.ink, opacity: 0.8 }, P));
    this.strips = fan.cx.map((x) => [0, 1, 2, 3].map((c) => el('rect', { x: x - 21 + c * 10.5, y: 628, width: 9.5, height: 20, rx: 2, fill: C.paper2 }, P)));
    this.conv = fan.cx.map(() => el('path', { fill: 'none', stroke: C.v, 'stroke-linecap': 'round' }, P));
    this.zM = Matrix(P, { x: 760, y: 722, rows: 1, cols: 4, cw: 54, ch: 38, kind: 'v', fs: 14 });
    this.zLab = label(P, 740, 747, '', { size: 16, cls: 'sans', anchor: 'end', weight: 700 });
    formula(P, '= \\sum_j a_j \\v{v_j}', { x: 996, y: 747, size: 20 });
    para(P, '（{m:a_j}：权重；{m:v_j}：第 {m:j} 个词的 value）', { x: 1110, y: 747, size: 13, cls: 'sans ink3' });
    this.vmax = vmax;
    const N = riseG(g, 420);
    para(N, '{b:animal → it 只隔 1 步}（RNN 要 6 步）；而且 11 个词的这些计算互不依赖，可以同时进行。', { x: 72, y: 816, w: 1400, size: 17 });
    para(N, '数值由页面脚本实时计算：演示用 {m:d_{model} = 6} 的小模型，参数为讲解专门构造，不是论文训练出的。第 3–5 步会把这些计算一步步拆开。', { x: 72, y: 852, w: 1440, size: 13.5, cls: 'sans ink3' });
    // value flow dots travelling from keys up to the query
    this.flow = TOK.map(() => el('circle', { r: 3, fill: C.v, class: 'flowdot', opacity: 0 }, R));
    this.sel = IT;
  },
  renderPipe(w) {
    const i = this.fan.sel, att = this.att;
    const cx = this.fan.cx;
    const zx = 760 + 108, zy = 718;
    const z = [0, 0, 0, 0];
    w.forEach((wj, j) => {
      this.scoreT[j].textContent = fx(att.S[i][j]);
      const h = 72 * wj;
      this.bars[j].setAttribute('y', (600 - h).toFixed(1));
      this.bars[j].setAttribute('height', h.toFixed(1));
      att.V[j].forEach((v, c) => {
        z[c] += wj * v;
        this.strips[j][c].setAttribute('fill', cellStyle('v', wj * v, this.vmax)[0]);
      });
      this.conv[j].setAttribute('d', `M${cx[j].toFixed(1)},652 Q${cx[j].toFixed(1)},${zy - 22} ${zx},${zy}`);
      this.conv[j].setAttribute('stroke-width', (0.6 + 7 * wj).toFixed(2));
      this.conv[j].setAttribute('stroke-opacity', (0.08 + 0.8 * Math.min(1, wj * 1.3)).toFixed(3));
    });
    this.zM.set([z], this.vmax);
    this.zLab.textContent = `${TOK[i]} 的新表示`;
  },
  select(i) { this.fan.select(i); },
  enter(tl) {
    this.fan.select(this.fan.sel, true);
    tl.at(900, () => tl.loop((ms) => {
      const w = this.fan.cur ? this.fan.cur.w : null;
      if (!w) return;
      this.fan.lines.forEach((p, j) => {
        const L = p.getTotalLength();
        const ph = ((ms / 1700) + j * 0.137) % 1;
        const pt = p.getPointAtLength(L * (1 - ph));
        const c = this.flow[j];
        c.setAttribute('cx', pt.x.toFixed(1)); c.setAttribute('cy', pt.y.toFixed(1));
        c.setAttribute('r', (1.6 + 5 * Math.sqrt(w[j])).toFixed(2));
        c.setAttribute('opacity', (Math.min(1, w[j] * 2.2) * Math.sin(Math.PI * ph)).toFixed(3));
      });
    }));
  },
  leave() { this.flow.forEach((c) => c.setAttribute('opacity', 0)); },
  key(k) {
    if (k === 'ArrowUp' || k === 'ArrowDown') {
      this.select((this.fan.sel + (k === 'ArrowDown' ? 1 : TOK.length - 1)) % TOK.length);
      return true;
    }
    return false;
  },
  auto(tl) {
    const seq = [IT, 10, 3, 9, IT];
    seq.forEach((i, k) => tl.at(1400 + k * 2600, () => this.select(i)));
    return 1400 + seq.length * 2600;
  },
});

