SC.push({
  kicker: 'STEP 3 · 论文 §3.2.1–3.2.2', short: 'Q / K / V',
  title: 'Q / K / V：同一个词的三种身份',
  lead: '每个词向量分别乘三个矩阵，得到 query、key、value 三个向量。整句话一起算，就是三次矩阵乘法。',
  keys: '鼠标悬停格子看计算',
  build(g) {
    header(g, this);
    const att = this.att = Model.single();
    const X = att.X;
    const Wm = [PARAMS.Wq0, PARAMS.Wk0, PARAMS.Wv0];
    const R = [att.Q, att.K, att.V];
    const names = ['Q', 'K', 'V'], hues = ['q', 'k', 'v'];
    // formulas + roles (top-left)
    const F = riseG(g, 120);
    const roles = ['{q:query}：我在找什么', '{k:key}：我能被怎样找到', '{v:value}：被找到时交出的内容'];
    ['\\q{Q} = X\\q{W^Q}', '\\k{K} = X\\k{W^K}', '\\v{V} = X\\v{W^V}'].forEach((tex, k) => {
      formula(F, tex, { x: 92, y: 262 + k * 48, size: 26 });
      para(F, roles[k], { x: 236, y: 260 + k * 48, size: 16, cls: 'sans ink2' });
    });
    // X
    const MX = riseG(g, 200);
    this.mX = Matrix(MX, { x: 196, y: 424, rows: 11, cols: 6, cw: 44, ch: 30, kind: 'x', rowLabels: TOK, lfs: 15 });
    this.mX.set(X);
    formula(MX, 'X', { x: 328, y: 790, size: 24, anchor: 'middle' });
    label(MX, 328, 812, '词向量 · 11 × 6', { size: 12.5, cls: 'sans ink3', anchor: 'middle' });
    for (let c = 0; c < 6; c++) label(MX, 196 + 44 * c + 22, 414, String(c + 1), { size: 11, cls: 'mono ink3', anchor: 'middle' });
    // W and results
    this.mW = []; this.mR = [];
    [512, 732, 952].forEach((x, k) => {
      const gW = riseG(g, 320 + k * 90);
      const mw = Matrix(gW, { x, y: 220, rows: 6, cols: 4, cw: 44, ch: 30, kind: 'w' + hues[k] });
      mw.set(Wm[k]);
      formula(gW, `\\${hues[k]}{W^${names[k]}}`, { x: x + 88, y: 208, size: 21, anchor: 'middle' });
      const gR = riseG(g, 380 + k * 90);
      const mr = Matrix(gR, { x, y: 424, rows: 11, cols: 4, cw: 44, ch: 30, kind: hues[k], onCell: (i, j, click) => this.inspect(k, i, j, click) });
      mr.set(R[k]);
      formula(gR, `\\${hues[k]}{${names[k]}}`, { x: x + 88, y: 790, size: 24, anchor: 'middle' });
      para(gR, k < 2 ? '11 × {m:d_k} = 11 × 4' : '11 × {m:d_v} = 11 × 4', { x: x + 88, y: 812, size: 12.5, cls: 'sans ink3', anchor: 'middle' });
      for (let c = 0; c < 4; c++) label(gR, x + 44 * c + 22, 414, String(c + 1), { size: 11, cls: 'mono ink3', anchor: 'middle' });
      this.mW.push(mw); this.mR.push(mr);
    });
    // right panel: dot-product breakdown
    const P = riseG(g, 520);
    el('rect', { x: 1162, y: 220, width: 366, height: 590, rx: 12, class: 'panel' }, P);
    label(P, 1184, 254, '一个格子是怎么算出来的', { size: 17, weight: 700 });
    this.fG = el('g', null, P);
    this.terms = [];
    for (let m = 0; m < 6; m++) {
      const y = 340 + m * 27;
      this.terms.push({
        idx: label(P, 1184, y, `m=${m + 1}`, { size: 13, cls: 'mono ink3' }),
        a: label(P, 1300, y, '', { size: 14.5, cls: 'mono', anchor: 'end' }),
        x: label(P, 1318, y, '×', { size: 14.5, cls: 'mono ink3', anchor: 'middle' }),
        b: label(P, 1386, y, '', { size: 14.5, cls: 'mono', anchor: 'end' }),
        r: label(P, 1506, y, '', { size: 14.5, cls: 'mono ink2', anchor: 'end' }),
      });
    }
    el('line', { x1: 1184, x2: 1506, y1: 500, y2: 500, stroke: C.ink2, 'stroke-width': 1 }, P);
    label(P, 1184, 528, '合计', { size: 15, weight: 700 });
    this.total = label(P, 1506, 529, '', { size: 20, cls: 'mono', anchor: 'end', weight: 700 });
    para(P, '每个格子 = {m:X} 的一行（一个词）与 {m:W} 的一列做点积。整张 {m:\\q{Q}} 就是 11 × 6 的矩阵乘以 6 × 4 的矩阵。', { x: 1184, y: 570, w: 326, size: 15, lh: 24, cls: 'sans ink2' });
    para(P, '演示：{m:d_{model} = 6}，{m:d_k = d_v = 4}。原论文 base：{m:d_{model} = 512}，每个头 {m:d_k = d_v = 64}。{m:W^Q}、{m:W^K}、{m:W^V} 在真实模型里是训练学到的，这里是讲解用的构造值。', { x: 1184, y: 680, w: 326, size: 13.5, lh: 22, cls: 'sans ink3' });
    label(riseG(g, 700), 196, 852, '把鼠标移到 Q、K、V 的任意格子上，右侧显示它的计算过程', { size: 14, cls: 'sans cq hint-pulse', weight: 600 });
    this.Wm = Wm; this.R = R; this.hues = hues; this.names = names;
  },
  inspect(k, i, j, click, nTerms) {
    if (click) userAct();
    if (this.lock && nTerms === undefined) return;
    const hue = this.hues[k], X = this.att.X, W = this.Wm[k];
    const n = nTerms === undefined ? 6 : nTerms;
    this.mX.unmarkAll(); this.mW.forEach((m) => m.unmarkAll()); this.mR.forEach((m) => m.unmarkAll());
    this.mX.mark('row', i, 0, i, 5, hue === 'q' ? '' : hue);
    this.mW[k].mark('col', 0, j, 5, j, hue === 'q' ? '' : hue);
    this.mR[k].mark('cell', i, j, i, j, 'ink');
    this.fG.textContent = '';
    const name = TOK[i].replace("'", '’');
    formula(this.fG, `\\${hue}{${this.names[k]}}_{${name},${j + 1}} = \\sum_m X_{${name},m} \\, \\${hue}{W^${this.names[k]}}_{m,${j + 1}}`, { x: 1184, y: 296, size: 19 });
    let s = 0;
    this.terms.forEach((t, m) => {
      const show = m < n;
      const a = X[i][m], b = W[m][j];
      [t.idx, t.a, t.x, t.b, t.r].forEach((e) => e.setAttribute('opacity', show ? 1 : 0.12));
      t.a.textContent = fx(a); t.b.textContent = fx(b);
      t.b.setAttribute('class', 'mono c' + hue);
      t.r.textContent = '= ' + fx(a * b, 3);
      if (show) s += a * b;
    });
    this.total.textContent = n === 6 ? fx(s, 2) : '…';
    this.total.setAttribute('class', 'mono c' + hue);
  },
  enter(tl) {
    this.lock = true;
    this.mR.forEach((m) => { m.hideAll(); m.unmarkAll(); });
    this.inspect(0, IT, 0, false, 0);
    // demo: build Q[it,1] term by term, then the other columns of that row
    for (let m = 1; m <= 6; m++) tl.at(1100 + m * 190, () => this.inspect(0, IT, 0, false, m));
    tl.at(1100 + 7 * 190, () => this.mR[0].showCell(IT, 0, true));
    for (let j = 1; j < 4; j++) tl.at(2600 + j * 520, () => { this.inspect(0, IT, j, false, 6); this.mR[0].showCell(IT, j, true); });
    tl.at(4900, () => {
      this.mX.unmarkAll(); this.mW.forEach((m) => m.unmarkAll()); this.mR.forEach((m) => m.unmarkAll());
    });
    this.mR.forEach((m, k) => m.reveal(tl, (i, j) => i * 4 + j, 1100, 5000 + k * 260));
    tl.at(6600, () => { this.lock = false; this.inspect(0, IT, 0, false, 6); });
  },
  auto(tl) {
    tl.at(8200, () => this.inspect(1, ANIMAL, 0, false, 6));
    tl.at(10200, () => this.inspect(2, ANIMAL, 2, false, 6));
    return 12400;
  },
});

// ===================================================================
//  Scenes 4–6: scores & scaling, softmax & weighted sum, multi-head
// ===================================================================
const DK_STEPS = [4, 8, 16, 32, 64, 128, 256, 512];
let EXP = null;
// random q, k with i.i.d. N(0,1) components; prefix sums give q·k for every d_k at once
function buildExperiment() {
  const gs = gaussian(mulberry32(20170612));
  const n = 1500, dots = {};
  DK_STEPS.forEach((d) => { dots[d] = new Float64Array(n); });
  for (let s = 0; s < n; s++) {
    let acc = 0, k = 0;
    for (let i = 0; i < 512; i++) {
      acc += gs() * gs();
      if (i + 1 === DK_STEPS[k]) { dots[DK_STEPS[k]][s] = acc; k++; }
    }
  }
  const gq = gaussian(mulberry32(34));
  const q = Array.from({ length: 512 }, gq);
  const keys = Array.from({ length: 11 }, () => Array.from({ length: 512 }, gq));
  const logits = {};
  DK_STEPS.forEach((d) => { logits[d] = keys.map((kv) => { let a = 0; for (let i = 0; i < d; i++) a += q[i] * kv[i]; return a; }); });
  return { dots, logits, n };
}

// ---------------------------------------------------------------- step 4
SC.push({
  kicker: 'STEP 4 · 论文 §3.2.1', short: '打分与缩放',
  title: '打分与缩放：{m:\\q{Q}\\k{K}^T / \\sqrt{d_k}}',
  lead: '每个 query 和每个 key 做点积，得到一张 11 × 11 的分数表，再统一除以 {m:\\sqrt{d_k}}。为什么要除？右边用随机向量做个实验。',
  keys: 'S 缩放开关 · ↑↓ 调 d_k',
  build(g) {
    header(g, this);
    const L = riseG(g, 150);
    const att0 = Model.single({ scale: true });
    this.rawMax = Math.max(...att0.raw.flat().map(Math.abs));
    this.mQ = Matrix(L, { x: 170, y: 400, rows: 11, cols: 4, cw: 40, ch: 30, kind: 'q', rowLabels: TOK, lfs: 14 });
    this.mKT = Matrix(L, { x: 370, y: 262, rows: 4, cols: 11, cw: 40, ch: 30, kind: 'k', colLabels: TOK });
    this.mS = Matrix(L, { x: 370, y: 400, rows: 11, cols: 11, cw: 40, ch: 30, kind: 's', fs: 11.5, onCell: (i, j, click) => this.pick(i, j, click) });
    this.mQ.set(att0.Q); this.mKT.set(LA.T(att0.K));
    formula(L, '\\q{Q}', { x: 250, y: 768, size: 24, anchor: 'middle' });
    formula(L, '\\k{K}^T', { x: 250, y: 334, size: 24, anchor: 'middle' });
    label(L, 250, 356, '（K 转置）', { size: 12.5, cls: 'sans ink3', anchor: 'middle' });
    this.sLab = el('g', null, L);
    this.sNote = el('g', null, L);
    this.callout = el('g', null, L);
    this.itNote = el('g', null, L);

    const R = riseG(g, 380);
    para(R, '为什么要除以 {m:\\sqrt{d_k}}？', { x: 880, y: 272, size: 22, weight: 700 });
    para(R, '设 {m:q}、{m:k} 的各分量相互独立、均值为 0、方差为 1，则点积 {m:q \\cdot k = \\sum_i q_i k_i} 的均值为 0、方差为 {m:d_k}（论文 §3.2.1 脚注）。{m:d_k} 越大，点积的绝对值越大，softmax 被推向「几乎只剩一个 1」的区域，梯度变得极小。', { x: 880, y: 310, w: 648, size: 16, lh: 26, cls: 'sans ink2' });
    this.dk = 64;
    this.slider = Slider(R, {
      x: 886, y: 456, w: 330, steps: DK_STEPS, value: 64, label: '维度 {m:d_k}（随机实验）',
      fmt: (v) => 'd_k = ' + v, onInput: (v) => { this.dk = v; this.updateExp(); },
    });
    this.tog = Toggle(R, { x: 1284, y: 456, label: '除以 {m:\\sqrt{d_k}}', value: ST.scale, onChange: (v) => { ST.scale = v; this.update(); } });
    // chart A: histogram
    this.histT = el('g', null, R);
    this.stdT = el('g', null, R);
    this.hist = [];
    const nb = 48;
    for (let b = 0; b < nb; b++) this.hist.push(el('rect', { x: 880 + b * (628 / nb) + 1, y: 614, width: 628 / nb - 2, height: 0, rx: 1.5, fill: C.ink, opacity: 0.78 }, R));
    el('line', { x1: 880, x2: 1508, y1: 614.5, y2: 614.5, class: 'axis' }, R);
    for (let v = -60; v <= 60; v += 20) {
      const x = 880 + ((v + 60) / 120) * 628;
      el('line', { x1: x, x2: x, y1: 615, y2: 620, class: 'axis' }, R);
      label(R, x, 634, String(v), { size: 11, cls: 'mono ink3', anchor: 'middle' });
    }
    // chart B: softmax of one query against 11 keys
    para(R, '一个 query 对 11 个随机 key 的 softmax 权重', { x: 880, y: 664, size: 14, cls: 'sans ink2' });
    this.sbars = []; this.snums = [];
    for (let j = 0; j < 11; j++) {
      const x = 886 + j * 37;
      this.sbars.push(el('rect', { x, y: 780, width: 26, height: 0, rx: 3, fill: C.k, opacity: 0.85 }, R));
      this.snums.push(label(R, x + 13, 780, '', { size: 10.5, cls: 'mono ink2', anchor: 'middle' }));
    }
    el('line', { x1: 880, x2: 1290, y1: 780.5, y2: 780.5, class: 'axis' }, R);
    label(R, 1322, 690, '最大权重', { size: 13, cls: 'sans ink3' });
    this.maxT = label(R, 1322, 728, '', { size: 30, cls: 'mono', weight: 700 });
    label(R, 1322, 758, 'softmax 梯度强度', { size: 13, cls: 'sans ink3' });
    this.jT = label(R, 1508, 758, '', { size: 13, cls: 'mono', anchor: 'end', weight: 700 });
    el('rect', { x: 1322, y: 768, width: 186, height: 9, rx: 4.5, fill: C.paper2, stroke: C.rule }, R);
    this.jBar = el('rect', { x: 1322, y: 768, width: 0, height: 9, rx: 4.5, fill: C.q }, R);
    label(R, 1322, 796, '雅可比范数 ‖∂a/∂s‖，上限约 0.5', { size: 11.5, cls: 'sans ink3' });
    para(R, '除以 {m:\\sqrt{d_k}} 后，分数的方差回到 1：无论 {m:d_k} 多大，softmax 都不会过早饱和，梯度保持在正常范围。', { x: 880, y: 842, w: 648, size: 16, lh: 26 });
    this.sel = [IT, ANIMAL];
  },
  update() {
    this.tog.set(ST.scale, false);
    const att = this.att = Model.single({ scale: ST.scale });
    this.mS.set(att.S, this.rawMax);
    this.sLab.textContent = '';
    formula(this.sLab, ST.scale ? '\\q{Q}\\k{K}^T / \\sqrt{d_k}' : '\\q{Q}\\k{K}^T', { x: 590, y: 768, size: 22, anchor: 'middle' });
    this.sNote.textContent = '';
    para(this.sNote, ST.scale ? '本例 {m:d_k = 4}：每个分数都除以 {m:\\sqrt{4} = 2}' : '缩放已关闭：直接使用点积', { x: 590, y: 794, size: 13.5, cls: 'sans ink3', anchor: 'middle' });
    this.pick(this.sel[0], this.sel[1], false, true);
    this.updateExp();
  },
  pick(i, j, click, silent) {
    if (click) userAct();
    this.sel = [i, j];
    const att = this.att;
    this.mQ.unmarkAll(); this.mKT.unmarkAll(); this.mS.unmarkAll();
    this.mQ.mark('r', i, 0, i, 3);
    this.mKT.mark('c', 0, j, 3, j, 'k');
    this.mS.mark('c', i, j, i, j, 'ink');
    const qi = TOK[i].replace("'", '’'), kj = TOK[j].replace("'", '’');
    this.callout.textContent = '';
    const raw = att.raw[i][j];
    const txt = ST.scale
      ? `{m:\\q{q_{${qi}}} \\cdot \\k{k_{${kj}}}} = ${fx(raw)}　→　÷ {m:\\sqrt{4}}　→　{b:${fx(raw / 2)}}`
      : `{m:\\q{q_{${qi}}} \\cdot \\k{k_{${kj}}}} = {b:${fx(raw)}}（未缩放）`;
    para(this.callout, '例：' + txt, { x: 170, y: 846, size: 16 });
    const r = att.A[i], m = argmax(r);
    this.itNote.textContent = '';
    para(this.itNote, `softmax 之后，{t:${TOK[i]}} 这一行最大的权重是 {b:${r[m].toFixed(2)}}（给 {t:${TOK[m]}}）`, { x: 170, y: 878, size: 14, cls: 'sans ink2' });
  },
  updateExp() {
    if (!EXP) EXP = buildExperiment();
    const d = this.dk, c = ST.scale ? 1 / Math.sqrt(d) : 1;
    const dots = EXP.dots[d];
    const nb = this.hist.length, bw = 120 / nb, counts = new Array(nb).fill(0);
    let s1 = 0, s2 = 0;
    for (let s = 0; s < dots.length; s++) {
      const v = dots[s] * c;
      s1 += v; s2 += v * v;
      const b = Math.floor((v + 60) / bw);
      if (b >= 0 && b < nb) counts[b]++;
    }
    const mean = s1 / dots.length, std = Math.sqrt(s2 / dots.length - mean * mean);
    const mc = Math.max(...counts);
    counts.forEach((n, b) => {
      const h = (n / mc) * 90;
      this.hist[b].setAttribute('y', (614 - h).toFixed(1));
      this.hist[b].setAttribute('height', h.toFixed(1));
    });
    this.histT.textContent = '';
    para(this.histT, ST.scale ? '1500 对随机向量，缩放后分数 {m:q \\cdot k / \\sqrt{d_k}} 的分布' : '1500 对随机向量，点积 {m:q \\cdot k} 的分布（未缩放）', { x: 880, y: 512, size: 14, cls: 'sans ink2' });
    this.stdT.textContent = '';
    para(this.stdT, `标准差 {b:${std.toFixed(2)}}（理论 ${ST.scale ? '1' : '{m:\\sqrt{' + d + '}} = ' + Math.sqrt(d).toFixed(2)}）`, { x: 1508, y: 512, size: 13.5, cls: 'sans', anchor: 'end' });
    const a = LA.softmax(EXP.logits[d].map((v) => v * c));
    a.forEach((w, j) => {
      const h = 84 * w;
      this.sbars[j].setAttribute('y', (780 - h).toFixed(1));
      this.sbars[j].setAttribute('height', h.toFixed(1));
      this.snums[j].setAttribute('y', (780 - h - 5).toFixed(1));
      this.snums[j].textContent = w.toFixed(2);
    });
    const mx = Math.max(...a), J = LA.jacNorm(a);
    this.maxT.textContent = mx.toFixed(3);
    this.maxT.setAttribute('fill', mx > 0.9 ? C.qd : C.ink);
    this.jT.textContent = J.toFixed(3);
    this.jBar.setAttribute('width', (186 * clamp(J / 0.5, 0, 1)).toFixed(1));
  },
  enter(tl) {
    this.update();
    this.mS.hideAll();
    this.pick(IT, ANIMAL, false, true);
    this.mS.reveal(tl, (i, j) => (i === IT && j === ANIMAL ? -1 : i + j + 0.01 * i), 1300, 1300);
  },
  key(k) {
    if (k === 's' || k === 'S') { ST.scale = !ST.scale; this.update(); return true; }
    if (k === 'ArrowUp' || k === 'ArrowDown') { this.slider.nudge(k === 'ArrowUp' ? 1 : -1); return true; }
    return false;
  },
  auto(tl) {
    tl.at(3800, () => { ST.scale = false; this.update(); });
    [128, 256, 512].forEach((d, k) => tl.at(5200 + k * 800, () => this.slider.set(d, true)));
    tl.at(9000, () => { ST.scale = true; this.update(); });
    tl.at(11200, () => this.slider.set(64, true));
    return 13200;
  },
});

