    });
    this.tog = Toggle(L, { x: 524, y: 752, label: '除以 {m:\\sqrt{d_k}}', value: ST.scale, onChange: (v) => { ST.scale = v; this.update(); } });
    para(L, '分数再除以 {m:\\tau} 后做 softmax：{m:\\tau < 1} 分布更尖，{m:\\tau > 1} 更平。{m:\\tau = 1} 就是论文公式——论文里没有 {m:\\tau}，这里只用它演示 softmax 的形状。', { x: 184, y: 812, w: 500, size: 13.5, lh: 22, cls: 'sans ink3' });

    const R = riseG(g, 320);
    const att = Model.single();
    this.vmax = Math.max(...att.V.flat().map(Math.abs));
    this.wHead = label(R, 752, 318, '', { size: 13.5, cls: 'sans cq', anchor: 'middle', weight: 700 });
    TOK.forEach((t, j) => label(R, 712, 330 + 30 * j + 19.5, t, { size: 13, cls: 'tok-t ink2', anchor: 'end' }));
    this.wg = el('g', null, R);
    this.wCells = TOK.map((_, j) => {
      const r = el('rect', { x: 723, y: 330 + 30 * j + 1, width: 58, height: 28, rx: 5, fill: C.paper2 }, this.wg);
      const t = el('text', { x: 752, y: 330 + 30 * j + 19.5, 'text-anchor': 'middle', class: 'mono', 'font-size': 12.5 }, this.wg);
      return { r, t };
    });
    label(R, 800, 506, '×', { size: 24, cls: 'sans ink3', anchor: 'middle' });
    this.mV = Matrix(R, { x: 818, y: 330, rows: 11, cols: 4, cw: 44, ch: 30, kind: 'v' });
    this.mV.set(att.V, this.vmax);
    formula(R, '\\v{V}', { x: 906, y: 318, size: 19, anchor: 'middle' });
    label(R, 1012, 506, '=', { size: 24, cls: 'sans ink3', anchor: 'middle' });
    this.mWV = Matrix(R, { x: 1030, y: 330, rows: 11, cols: 4, cw: 44, ch: 30, kind: 'v' });
    formula(R, 'a_j \\v{v_j}', { x: 1118, y: 318, size: 18, anchor: 'middle' });
    el('line', { x1: 1026, x2: 1210, y1: 670, y2: 670, stroke: C.ink, 'stroke-width': 1.4 }, R);
    label(R, 1016, 704, 'Σ', { size: 22, cls: 'serif ink2', anchor: 'end' });
    this.mZ1 = Matrix(R, { x: 1030, y: 680, rows: 1, cols: 4, cw: 44, ch: 34, kind: 'v', fs: 13 });
    this.zForm = el('g', null, R);
    this.mZ = Matrix(R, { x: 1300, y: 330, rows: 11, cols: 4, cw: 44, ch: 30, kind: 'v', rowLabels: TOK, lfs: 13, onRow: (i) => { userAct(); this.select(i); } });
    formula(R, 'Z = A\\v{V}', { x: 1388, y: 318, size: 18, anchor: 'middle' });
    label(R, 1388, 690, '每个词都这样算一遍', { size: 13, cls: 'sans ink3', anchor: 'middle' });
    this.note = el('g', null, R);
    this.sel = IT;
  },
  update() {
    this.tog.set(ST.scale, false);
    this.tau.set(ST.tau, false);
    const att = this.att = Model.single({ scale: ST.scale, tau: ST.tau });
    this.mA.set(att.A, 1);
    att.A.forEach((r, i) => { this.rs[i].textContent = sum(r).toFixed(2); });
    const zmax = this.vmax;
    this.mZ.set(att.Z, zmax);
    this.updateSel();
  },
  updateSel() {
    const i = this.sel, att = this.att, w = att.A[i];
    this.mA.unmarkAll(); this.mZ.unmarkAll(); this.mZ1.unmarkAll();
    this.mA.mark('r', i, 0, i, 10);
    this.mZ.mark('r', i, 0, i, 3);
    this.mZ1.mark('r', 0, 0, 0, 3);
    this.wHead.textContent = `${TOK[i]} 的权重`;
    w.forEach((v, j) => {
      const [f, tf] = cellStyle('a', v);
      this.wCells[j].r.setAttribute('fill', f);
      this.wCells[j].t.setAttribute('fill', tf);
      this.wCells[j].t.textContent = v.toFixed(2);
    });
    this.mWV.set(att.V.map((row, j) => row.map((v) => v * w[j])), this.vmax);
    this.mZ1.set([att.Z[i]], this.vmax);
    const name = TOK[i].replace("'", '’');
    this.zForm.textContent = '';
    formula(this.zForm, `z_{${name}} = \\sum_j a_{${name},j} \\v{v_j}`, { x: 1118, y: 750, size: 17, anchor: 'middle' });
    const m = argmax(w);
    this.note.textContent = '';
    para(this.note, `每行权重都为正、和为 1，所以输出是各个 value 的{b:加权平均}：{t:${TOK[i]}} 的输出里，{t:${TOK[m]}} 的 value 占了 {b:${Math.round(w[m] * 100)}%}。`, { x: 722, y: 812, w: 806, size: 16, lh: 26 });
  },
  select(i, instant) {
    const from = this.sel;
    this.sel = i;
    if (instant || FLUSH) { this.updateSel(); return; }
    // the chosen heatmap row flies over and turns into the weight column
    const att = this.att, row = att.A[i];
    const fg = el('g', { 'pointer-events': 'none' }, this.wg.parentNode);
    const parts = row.map((v, j) => {
      const [f, tf] = cellStyle('a', v);
      const r = el('rect', { rx: 5, fill: f }, fg);
      const t = el('text', { 'text-anchor': 'middle', class: 'mono', 'font-size': 12, fill: tf }, fg, v.toFixed(2));
      return { r, t, x0: 184 + 36 * j + 1, y0: 330 + 30 * i + 1, x1: 723, y1: 330 + 30 * j + 1 };
    });
    this.wg.setAttribute('opacity', 0.15);
    this.mA.unmarkAll(); this.mA.mark('r', i, 0, i, 10);
    tween(700, (p) => {
      parts.forEach((pt, j) => {
        const q = clamp(p * 1.25 - j * 0.025, 0, 1), e = EASE.io(q);
        const x = lerp(pt.x0, pt.x1, e), y = lerp(pt.y0, pt.y1, e), w = lerp(34, 58, e);
        pt.r.setAttribute('x', x.toFixed(1)); pt.r.setAttribute('y', y.toFixed(1));
        pt.r.setAttribute('width', w.toFixed(1)); pt.r.setAttribute('height', 28);
        pt.t.setAttribute('x', (x + w / 2).toFixed(1)); pt.t.setAttribute('y', (y + 18.5).toFixed(1));
      });
    }, EASE.lin, () => { fg.remove(); this.wg.setAttribute('opacity', 1); this.updateSel(); });
    if (from === i) this.updateSel();
  },
  enter() { this.update(); },
  key(k) {
    if (k === 'ArrowUp' || k === 'ArrowDown') { this.select((this.sel + (k === 'ArrowDown' ? 1 : 10)) % 11); return true; }
    if (k === '[' || k === ']') { this.tau.nudge(k === ']' ? 1 : -1); return true; }
    if (k === 's' || k === 'S') { ST.scale = !ST.scale; this.update(); return true; }
    return false;
  },
  auto(tl) {
    tl.at(1600, () => this.select(10));
    tl.at(3600, () => this.select(IT));
    const taus = [[5600, 0.6], [6200, 0.35], [7800, 1.8], [8400, 3.5], [10000, 1]];
    taus.forEach(([t, v]) => tl.at(t, () => { ST.tau = v; this.update(); }));
    tl.at(11600, () => this.select(9));
    return 13800;
  },
});

