    });
    label(T, tx + 8, 343, '头的名字只是我们对这组演示参数的解读', { size: 13, cls: 'sans ink3' });
    // fan
    const R = riseG(g, 260);
    const rl = (y, s) => label(R, 208, y, s, { size: 14, cls: 'sans ink3', anchor: 'end' });
