      const m = Matrix(B, {
        x, y: 662, rows: 11, cols: 11, cw: 13, ch: 13, gap: 1, kind: 'a', numbers: false, bracket: false,
        rowLabels: h === 0 ? TOK : null, lfs: 10.5,
        onCell: (i, j, click) => { if (click) { userAct(); this.setHead(h); } },
      });
      m.set(mh.hs[h].A, 1);
