    label(P, 960, 826, 'Concat · 11 × 6', { size: 12.5, cls: 'sans ink2', anchor: 'middle' });
    label(P, 1033, 739, '×', { size: 20, cls: 'sans ink3', anchor: 'middle' });
    this.oG = el('g', null, P);
