    this.roV = [0, 1, 2, 3, 4, 5].map((k) => label(this.oG, 1340 + (k % 2) * 92, 704 + Math.floor(k / 2) * 24, '', { size: 13.5, cls: 'mono' }));
    label(this.oG, 1340, 788, '与输入同为 6 维，', { size: 12.5, cls: 'sans ink3' });
    label(this.oG, 1340, 808, '可以继续送入下一层', { size: 12.5, cls: 'sans ink3' });
