    this.tabs.forEach((b, k) => b.setOn(k === h));
    const m = this.minis[h];
    this.outline.setAttribute('x', m.x - 5); this.outline.setAttribute('y', m.y - 5);
    this.fan.refresh();
  },
  select(i) {
    this.fan.select(i);
    this.markRow(i);
  },
  markRow(i) {
    this.minis.forEach((m) => { m.unmarkAll(); m.mark('r', i, 0, i, 10); });
    this.hM.forEach((m) => { m.unmarkAll(); m.mark('r', i, 0, i, 1); });
    this.cM.unmarkAll(); this.cM.mark('r', i, 0, i, 5);
    this.oM.unmarkAll(); this.oM.mark('r', i, 0, i, 5);
    this.roT.textContent = `${TOK[i]} 的输出行：`;
    this.mh.out[i].forEach((v, k) => { this.roV[k].textContent = fsig(v); });
  },
  enter(tl) {
    this.setHead(this.head);
    this.fan.select(this.fan.sel, true);
    this.markRow(this.fan.sel);
    // head outputs slide into the concatenated matrix, then W^O and the output appear
    this.cM.g.setAttribute('opacity', 0);
    this.oG.setAttribute('opacity', 0);
