      });
      this.cM.g.setAttribute('opacity', p.toFixed(2));
    }, EASE.io, () => clones.forEach((c) => c.remove())));
    tl.at(2400, () => tl.tween(600, (p) => this.oG.setAttribute('opacity', p.toFixed(2)), EASE.out));
    if (FLUSH) clones.forEach((c) => c.remove());
  },
  leave() { this.P.querySelectorAll(':scope > g.mat[pointer-events]').forEach((c) => c.remove()); },
  key(k) {
