    tl.at(13600, () => { this.setHead(0); this.select(IT); });
    return 15800;
  },
});

// ===================================================================
//  Scenes 7–8: positional encoding, summary
// ===================================================================
const PE_DIMS = [0, 1, 64, 128, 256];
const pe = (pos, d, dm) => {
  const f = Math.pow(10000, -(d - (d % 2)) / (dm || 512));
  return d % 2 ? Math.cos(pos * f) : Math.sin(pos * f);
};
// ---------------------------------------------------------------- step 7
SC.push({
  kicker: 'STEP 7 · 论文 §3.5', short: '位置编码',
  title: '位置编码：注意力本身不知道词序',
  lead: '注意力只比较内容、不看位置：把句子打乱，每一对词之间的权重都不变。所以论文给每个位置加上一个随位置变化的正弦 / 余弦信号——位置编码。',
  leadW: 1456,
  keys: 'R 打乱 / 还原 · ↑↓ 换词 · [ ] 移动位置',
  build(g) {
