    this.lines = TOK.map(() => el('path', { fill: 'none', stroke: 'url(#vfGrad)', 'stroke-linecap': 'round' }, lineG));
    const fs = 17;
    this.rq = TOK.map((t, i) => {
      const w = measure(t, 'tok-t', fs);
      const tg = el('g', { class: 'tok' }, L);
      el('rect', { class: 'pill', x: -w - 8, y: -fs * 0.95, width: w + 16, height: fs * 1.4, rx: 7 }, tg);
      el('text', { class: 'tok-t', 'text-anchor': 'end', 'font-size': fs }, tg, t);
      tg.addEventListener('click', () => { userAct(); this.select(i); });
      return tg;
    });
    this.rk = TOK.map((t) => {
      const w = measure(t, 'tok-t', fs);
      const tg = el('g', { class: 'keytok' }, L);
      const pill = el('rect', { x: -8, y: -fs * 0.95, width: w + 16, height: fs * 1.4, rx: 7, fill: 'transparent' }, tg);
      el('text', { class: 'tok-t', 'font-size': fs }, tg, t);
      const num = el('text', { class: 'mono wlab', 'text-anchor': 'end', 'font-size': 14, x: 180 }, tg);
      return { g: tg, pill, num };
    });
    const bx = Button(L, { x: 96, y: 666, h: 36, label: '打乱词序', kind: 'primary', onClick: () => { userAct(); this.shuffle(); } });
    this.bRestore = Button(L, { x: 96 + bx.w + 12, y: 666, h: 36, label: '还原', onClick: () => { userAct(); this.restore(); } });
    this.cap = el('g', null, L);
    para(L, '注意力只看内容。演示里两个 the 是同一个词向量，所以它们得到的注意力也完全相同——模型分不出谁在前、谁在后。', { x: 72, y: 818, w: 660, size: 14.5, lh: 23, cls: 'sans ink2' });
    this.perm = TOK.map((_, i) => i);
    this.sel = IT;
    this.rng = mulberry32(1706);
    this.base = Model.single();

    // right: sinusoidal encoding
    const R = riseG(g, 330);
    formula(R, 'PE_{(pos, 2i)} = sin(pos / 10000^{2i/d_{model}})', { x: 820, y: 240, size: 21 });
    formula(R, 'PE_{(pos, 2i+1)} = cos(pos / 10000^{2i/d_{model}})', { x: 820, y: 286, size: 21 });
    para(R, '原论文设定 {m:d_{model} = 512}', { x: 1528, y: 240, size: 12.5, cls: 'sans ink3', anchor: 'end' });
    const X0c = 930, W = 500, xOf = (p) => X0c + (p / 63) * W;
    this.xOf = xOf;
    this.lanes = PE_DIMS.map((d, k) => {
