      return { yc, d, dot: null, val: label(R, 1444, yc + 4.5, '', { size: 13, cls: 'mono' }) };
    });
    el('line', { x1: X0c, x2: X0c + W, y1: 562, y2: 562, class: 'axis' }, R);
    for (let p = 0; p <= 60; p += 10) {
      el('line', { x1: xOf(p), x2: xOf(p), y1: 562, y2: 567, class: 'axis' }, R);
      label(R, xOf(p), 580, String(p), { size: 11, cls: 'mono ink3', anchor: 'middle' });
    }
    label(R, X0c + W, 598, '位置 pos', { size: 12, cls: 'sans ink3', anchor: 'end' });
    this.cursor = el('line', { y1: 318, y2: 556, stroke: C.q, 'stroke-width': 1.6 }, R);
    this.lanes.forEach((ln) => { ln.dot = el('circle', { r: 4.5, fill: C.q }, R); });
    this.posS = Slider(R, {
      x: 934, y: 644, w: 492, min: 0, max: 63, value: 17, round: Math.round, nudge: 1 / 63,
      label: '位置 {m:pos}（拖动）', fmt: (v) => 'pos = ' + v, onInput: (v) => this.setPos(v),
    });
    this.barLab = el('g', null, R);
    this.bars = [];
    for (let d = 0; d < 128; d++) this.bars.push(el('rect', { x: X0c + d * (W / 128), y: 692, width: W / 128 - 0.6, height: 22, fill: C.ink }, R));
    const notes = [
      '① 位置编码与词向量维度相同（都是 {m:d_{model}}），两者{b:直接相加}后送入第一层。',
      '② 各维波长从 {m:2π} 到 {m:10000 \\cdot 2π} 呈几何级数；对任意固定偏移 {m:k}，{m:PE_{pos+k}} 都能写成 {m:PE_{pos}} 的线性函数——论文推测这让模型更容易学会按相对位置关注。',
      '③ 论文也试过可学习的位置嵌入，结果几乎相同（表 3 (E)）；选正弦版本是因为它可能外推到比训练时更长的句子。',
    ];
    let ny = 752;
    notes.forEach((s) => { const p = para(R, s, { x: 820, y: ny, w: 708, size: 14.5, lh: 22, cls: 'sans ink2' }); ny += p.h + 6; });
  },
  yOf(p) { return 304 + 34 * p; },
  layout(posOf) {
    this.rq.forEach((tg, t) => tg.setAttribute('transform', `translate(262,${this.yOf(posOf[t]).toFixed(1)})`));
    this.rk.forEach((r, t) => r.g.setAttribute('transform', `translate(520,${this.yOf(posOf[t]).toFixed(1)})`));
    const s = this.sel, ys = this.yOf(posOf[s]) - 5.5;
    const w = this.w;
    this.lines.forEach((p, t) => {
      const yt = this.yOf(posOf[t]) - 5.5;
      p.setAttribute('d', `M272,${ys.toFixed(1)} C390,${ys.toFixed(1)} 392,${yt.toFixed(1)} 510,${yt.toFixed(1)}`);
      p.setAttribute('stroke-width', (0.8 + 15 * w[t]).toFixed(2));
      p.setAttribute('stroke-opacity', (0.1 + 0.9 * Math.min(1, w[t] * 1.2)).toFixed(3));
    });
  },
  compute() {
    // recompute attention on the permuted sentence from scratch
    const perm = this.perm;
    const posOf = []; perm.forEach((t, p) => { posOf[t] = p; });
    const att = Model.single({}, perm.map((t) => X0[t]));
    const s = this.sel;
    this.w = TOK.map((_, t) => att.A[posOf[s]][posOf[t]]);
    let diff = 0;
    for (let a = 0; a < 11; a++) for (let b = 0; b < 11; b++) diff = Math.max(diff, Math.abs(att.A[posOf[a]][posOf[b]] - this.base.A[a][b]));
    this.diff = diff;
    this.posOf = posOf;
    const mx = argmax(this.w);
    this.rq.forEach((tg, t) => tg.classList.toggle('sel', t === s));
    this.rk.forEach((r, t) => {
      r.pill.setAttribute('fill', rgba(RGB.k, Math.min(0.6, this.w[t] * 0.75)));
      r.num.textContent = this.w[t].toFixed(2);
      r.num.setAttribute('fill', t === mx ? C.kd : this.w[t] >= 0.1 ? C.ink : C.ink3);
    });
    const shuffled = perm.some((t, p) => t !== p);
    const orig = this.base.A[s][mx];
    this.cap.textContent = '';
    const head = `{t:${TOK[s]}} → {t:${TOK[mx]}} = {b:${this.w[mx].toFixed(2)}}`;
    const txt = shuffled
      ? `打乱后重新计算：${head}（打乱前 ${orig.toFixed(2)}）。逐对比较所有 121 个权重，最大差异 = {b:${diff.toFixed(6)}}——只是跟着换了位置。`
      : `原始顺序：${head}。点「打乱词序」，页面会对打乱后的句子从头重算一遍注意力。`;
    para(this.cap, txt, { x: 72, y: 742, w: 660, size: 16, lh: 26 });
    this.bRestore.setDisabled(!shuffled);
  },
  moveTo(newPerm) {
    const oldPos = this.posOf.slice();
    this.perm = newPerm;
    this.compute();
    const target = this.posOf;
    tween(FLUSH ? 0 : 750, (p) => {
      this.layout(oldPos.map((o, t) => lerp(o, target[t], p)));
    }, EASE.io);
  },
  shuffle() {
    let perm;
    do {
      perm = TOK.map((_, i) => i);
      for (let i = perm.length - 1; i > 0; i--) { const j = Math.floor(this.rng() * (i + 1)); [perm[i], perm[j]] = [perm[j], perm[i]]; }
    } while (perm.filter((t, p) => t === p).length > 2);
    this.moveTo(perm);
  },
  restore() { this.moveTo(TOK.map((_, i) => i)); },
  select(i) {
    this.sel = i;
    this.compute();
    this.layout(this.posOf);
  },
  setPos(v) {
    const x = this.xOf(v);
    this.cursor.setAttribute('x1', x); this.cursor.setAttribute('x2', x);
    this.lanes.forEach((ln) => {
      const val = pe(v, ln.d);
      ln.dot.setAttribute('cx', x); ln.dot.setAttribute('cy', (ln.yc - 17 * val).toFixed(1));
      ln.val.textContent = fsig(val);
    });
    this.bars.forEach((b, d) => {
      const val = pe(v, d);
      b.setAttribute('fill', val >= 0 ? rgba(RGB.ink, 0.1 + 0.8 * val) : rgba(RGB.gray, 0.08 + 0.25 * -val));
    });
    this.barLab.textContent = '';
    para(this.barLab, `pos = ${v} 的位置编码向量（前 128 维；深 = 正，浅 = 负）`, { x: 930, y: 684, size: 12.5, cls: 'sans ink3' });
  },
  enter() {
    this.compute();
    this.layout(this.posOf);
    this.setPos(this.posS.v);
  },
  key(k) {
    if (k === 'r' || k === 'R') { if (this.perm.some((t, p) => t !== p)) this.restore(); else this.shuffle(); return true; }
    if (k === 'ArrowUp' || k === 'ArrowDown') { this.select((this.sel + (k === 'ArrowDown' ? 1 : 10)) % 11); return true; }
    if (k === '[' || k === ']') { this.posS.nudge(k === ']' ? 1 : -1); return true; }
    return false;
  },
  auto(tl) {
    tl.at(1600, () => this.shuffle());
    tl.at(4600, () => this.shuffle());
    tl.at(7400, () => this.restore());
    tl.at(8400, () => tl.tween(3000, (p) => this.posS.set(Math.round(lerp(17, 52, p)), true), EASE.io));
    return 12800;
  },
});

// ---------------------------------------------------------------- step 8
function drawTransformer(g, self) {
  const ex = 270, dx = 610, bw = 206, hw = bw / 2;
  const FILL = { attn: '#FBE6D2', ff: '#E4EDF6', norm: '#F4EFDC', emb: '#F0E8DC', lin: C.paper2 };
  const blk = (cx, y, h, txt, fill, size) => {
    box(g, cx - hw, y, bw, h, { rx: 6, fill, stroke: C.ink2, sw: 1.1 });
    label(g, cx, y + h / 2 + (size || 14) * 0.36, txt, { size: size || 14, anchor: 'middle', weight: 600, cls: 'serif' });
  };
  const plus = (cx, cy) => {
    el('circle', { cx, cy, r: 11, fill: C.paper, stroke: C.ink2, 'stroke-width': 1.3 }, g);
    el('path', { d: `M${cx - 6},${cy} H${cx + 6} M${cx},${cy - 6} V${cy + 6}`, stroke: C.ink2, 'stroke-width': 1.5 }, g);
  };
  const peIcon = (cx, cy) => {
    el('circle', { cx, cy, r: 15, fill: C.paper, stroke: C.ink2, 'stroke-width': 1.2 }, g);
    el('path', { d: `M${cx - 10},${cy} C${cx - 6},${cy - 12} ${cx - 3},${cy - 12} ${cx},${cy} S${cx + 6},${cy + 12} ${cx + 10},${cy}`, fill: 'none', stroke: C.ink2, 'stroke-width': 1.4 }, g);
  };
  const qkv = (cx, y0, y1) => {
    el('path', { d: `M${cx - 44},${y0} H${cx + 44}`, stroke: C.ink2, 'stroke-width': 1.3 }, g);
    arrow(g, `M${cx - 44},${y0} V${y1}`, { stroke: C.q, marker: 'arrQ', w: 1.6 });
    arrow(g, `M${cx},${y0} V${y1}`, { stroke: C.k, marker: 'arrK', w: 1.6 });
    arrow(g, `M${cx + 44},${y0} V${y1}`, { stroke: C.v, marker: 'arrV', w: 1.6 });
  };
  // stacked "cards" behind the N× frames
  const gh = el('g', null, g);
  self.ghosts = [];
  for (let k = 5; k >= 1; k--) {
    self.ghosts.push([k, el('rect', { x: ex - 125, y: 480, width: 250, height: 258, rx: 12, fill: C.paper, stroke: '#CFC5B3' }, gh)]);
    self.ghosts.push([k, el('rect', { x: dx - 125, y: 344, width: 250, height: 394, rx: 12, fill: C.paper, stroke: '#CFC5B3' }, gh)]);
  }
  el('rect', { x: ex - 125, y: 480, width: 250, height: 258, rx: 12, fill: '#F4EFE5', stroke: C.ink3, 'stroke-width': 1.2 }, g);
  el('rect', { x: dx - 125, y: 344, width: 250, height: 394, rx: 12, fill: '#F4EFE5', stroke: C.ink3, 'stroke-width': 1.2 }, g);
  self.nx = [label(g, ex - 140, 616, 'N×', { size: 21, weight: 700, anchor: 'end', cls: 'serif' }),
    label(g, dx + 166, 548, 'N×', { size: 21, weight: 700, cls: 'serif' })];
  label(g, ex, 422, '编码器', { size: 18, weight: 700, anchor: 'middle' });
  label(g, ex, 443, 'Encoder', { size: 13, cls: 'serif ink3', anchor: 'middle' });
  label(g, dx + 128, 280, '解码器', { size: 18, weight: 700 });
  label(g, dx + 128, 301, 'Decoder', { size: 13, cls: 'serif ink3' });

  // encoder
  label(g, ex, 878, 'Inputs', { size: 14, anchor: 'middle', cls: 'serif' });
  arrow(g, `M${ex},862 V840`);
  blk(ex, 802, 34, 'Input Embedding', FILL.emb);
  arrow(g, `M${ex},802 V786`);
  plus(ex, 772); peIcon(ex - 62, 772);
  el('line', { x1: ex - 47, x2: ex - 11, y1: 772, y2: 772, stroke: C.ink2, 'stroke-width': 1.2 }, g);
  label(g, ex - 84, 768, 'Positional', { size: 12, cls: 'serif ink2', anchor: 'end' });
  label(g, ex - 84, 783, 'Encoding', { size: 12, cls: 'serif ink2', anchor: 'end' });
  el('path', { d: `M${ex},761 V718`, stroke: C.ink2, 'stroke-width': 1.3, fill: 'none' }, g);
  qkv(ex, 718, 702);
  blk(ex, 656, 44, 'Multi-Head Attention', FILL.attn);
  arrow(g, `M${ex},656 V640`);
  blk(ex, 608, 28, 'Add & Norm', FILL.norm, 13);
  arrow(g, `M${ex},608 V596`);
  blk(ex, 548, 44, 'Feed Forward', FILL.ff);
  arrow(g, `M${ex},548 V528`);
  blk(ex, 496, 28, 'Add & Norm', FILL.norm, 13);
  arrow(g, `M${ex},730 H${ex - 116} V622 H${ex - hw - 2}`, { w: 1.2 });
  arrow(g, `M${ex},602 H${ex - 116} V510 H${ex - hw - 2}`, { w: 1.2 });
  // encoder output -> decoder cross-attention (K, V)
  el('path', { d: `M${ex},496 V466 H440 V588 H${dx}`, stroke: C.ink2, 'stroke-width': 1.4, fill: 'none' }, g);
  arrow(g, `M${dx - 44},588 V568`, { stroke: C.k, marker: 'arrK', w: 1.6 });
  arrow(g, `M${dx},588 V568`, { stroke: C.v, marker: 'arrV', w: 1.6 });

  // decoder
  label(g, dx, 878, 'Outputs (shifted right)', { size: 14, anchor: 'middle', cls: 'serif' });
  arrow(g, `M${dx},862 V840`);
  blk(dx, 802, 34, 'Output Embedding', FILL.emb);
  arrow(g, `M${dx},802 V786`);
  plus(dx, 772); peIcon(dx + 62, 772);
  el('line', { x1: dx + 11, x2: dx + 47, y1: 772, y2: 772, stroke: C.ink2, 'stroke-width': 1.2 }, g);
  label(g, dx + 84, 768, 'Positional', { size: 12, cls: 'serif ink2' });
  label(g, dx + 84, 783, 'Encoding', { size: 12, cls: 'serif ink2' });
  el('path', { d: `M${dx},761 V718`, stroke: C.ink2, 'stroke-width': 1.3, fill: 'none' }, g);
  qkv(dx, 718, 702);
  blk(dx, 656, 44, 'Masked Multi-Head Attention', FILL.attn, 13);
  arrow(g, `M${dx},656 V640`);
  blk(dx, 608, 28, 'Add & Norm', FILL.norm, 13);
  arrow(g, `M${dx + 44},608 V568`, { stroke: C.q, marker: 'arrQ', w: 1.6 });
  blk(dx, 520, 44, 'Multi-Head Attention', FILL.attn);
  arrow(g, `M${dx},520 V504`);
  blk(dx, 472, 28, 'Add & Norm', FILL.norm, 13);
  arrow(g, `M${dx},472 V456`);
  blk(dx, 408, 44, 'Feed Forward', FILL.ff);
  arrow(g, `M${dx},408 V392`);
  blk(dx, 360, 28, 'Add & Norm', FILL.norm, 13);
  arrow(g, `M${dx},730 H${dx + 116} V622 H${dx + hw + 2}`, { w: 1.2 });
  arrow(g, `M${dx + 44},598 H${dx + 116} V486 H${dx + hw + 2}`, { w: 1.2 });
  arrow(g, `M${dx},462 H${dx + 116} V374 H${dx + hw + 2}`, { w: 1.2 });
  arrow(g, `M${dx},360 V336`);
  blk(dx, 304, 28, 'Linear', FILL.lin, 13);
  arrow(g, `M${dx},304 V290`);
  blk(dx, 258, 28, 'Softmax', FILL.lin, 13);
  arrow(g, `M${dx},258 V240`);
  label(g, dx, 230, 'Output Probabilities', { size: 14, anchor: 'middle', cls: 'serif' });
  label(g, 90, 236, '结构示意，按论文图 1 重绘', { size: 13, cls: 'sans ink3' });
  para(g, '彩色箭头：{q:Q} 橙　{k:K} 蓝　{v:V} 绿', { x: 90, y: 258, size: 13, cls: 'sans ink3' });
}
SC.push({
  kicker: 'STEP 8 · 论文 §3.1 / §4', short: '小结',
  title: '小结：把注意力堆起来，就是 Transformer',
  lead: '编码器和解码器各由 {m:N = 6} 个相同的层堆叠而成。每层的核心是多头注意力，外加逐位置的前馈网络；每个子层外面都有残差连接和层归一化。',
  build(g) {
    header(g, this);
    drawTransformer(riseG(g, 150), this);
    const R = riseG(g, 380);
    label(R, 850, 238, '为什么重要', { size: 22, weight: 700 });
    const cards = [
      ['并行', '一层之内所有位置同时计算：顺序操作 {m:O(1)}，RNN 为 {m:O(n)}。训练时可以大规模并行。'],
      ['长距离依赖', '任意两个位置之间的路径长度 {m:O(1)}，RNN 为 {m:O(n)}：animal 和 it 直接相连。'],
      ['多个角度', '多头注意力在不同的表示子空间里，同时关注不同位置、不同关系。'],
      ['代价', '每层计算量 {m:O(n^2 \\cdot d)}，随句子长度平方增长（论文表 1）。'],
    ];
    let y = 282;
    cards.forEach(([t, s], k) => {
      const cg = riseG(R, 460 + k * 110);
      el('circle', { cx: 866, cy: y - 6, r: 14, fill: k === 3 ? C.ink3 : C.ink }, cg);
      label(cg, 866, y - 1, String(k + 1), { size: 14, weight: 700, anchor: 'middle', fill: C.paper, cls: 'mono' });
      label(cg, 892, y, t, { size: 18, weight: 700 });
      const p = para(cg, s, { x: 892, y: y + 28, w: 636, size: 15.5, lh: 25, cls: 'sans ink2' });
      y += 28 + p.h + 22;
    });
    const F = riseG(g, 900);
    el('rect', { x: 850, y: 652, width: 678, height: 106, rx: 10, class: 'panel' }, F);
    label(F, 870, 681, '原论文 base 模型', { size: 15, weight: 700 });
    para(F, '{m:N = 6}　　{m:d_{model} = 512}　　{m:h = 8}　　{m:d_k = d_v = 64}　　{m:d_{ff} = 2048}', { x: 870, y: 712, size: 16 });
    para(F, '论文报告：WMT 2014 英→德翻译 {b:28.4 BLEU}（Transformer big，见论文摘要）', { x: 870, y: 742, size: 14, cls: 'sans ink2' });
    const C8 = riseG(g, 1000);
    label(C8, 850, 802, '回顾', { size: 14, cls: 'sans ink3' });
    let cx = 900, cy = 784;
    SC.slice(1).forEach((s, k) => {
      const w = Math.ceil(measure(`${k + 1} ${s.short}`, 'sans', 14, 600) + 28);
      if (cx + w > 1528) { cx = 900; cy += 40; }
      Button(C8, { x: cx, y: cy, h: 30, size: 14, label: `${k + 1} ${s.short}`, kind: 'chip', onClick: () => go(k + 1) });
      cx += w + 8;
    });
  },
  enter(tl) {
    this.ghosts.forEach(([, r]) => r.setAttribute('transform', 'translate(0,0)'));
    this.nx.forEach((t) => { t.textContent = 'N×'; });
    tl.at(900, () => tl.tween(1100, (p) => {
      this.ghosts.forEach(([k, r]) => r.setAttribute('transform', `translate(${(4 * k * p).toFixed(1)},${(-4 * k * p).toFixed(1)})`));
    }, EASE.out, () => this.nx.forEach((t) => { t.textContent = '6×'; })));
  },
  dwell: 9000,
});

// ===================================================================
//  Navigation, autoplay, keyboard
// ===================================================================
const stage = document.getElementById('stage');
const chrome = document.getElementById('chrome');
const scenes = SC.map((def, i) => {
  const g = el('g', { class: 'scene', id: 'scene-' + i, 'data-step': i }, stage);
  def.g = g; def.index = i;
  def.build(g);
  return def;
});
const LAST = scenes.length - 1;
let cur = -1, autoplay = false, autoTL = null;
const ui = {};

function userAct() { if (autoplay) stopAuto(); }

function buildChrome() {
  el('line', { x1: 72, x2: 1528, y1: 914, y2: 914, class: 'rule' }, chrome);
  ui.prog = el('line', { x1: 72, x2: 72, y1: 914, y2: 914, stroke: C.q, 'stroke-width': 3, 'stroke-linecap': 'round' }, chrome);
  ui.prev = Button(chrome, { x: 72, y: 932, h: 36, label: '‹ 上一步', onClick: () => go(cur - 1) });
  ui.next = Button(chrome, { x: 72 + ui.prev.w + 10, y: 932, h: 36, label: '下一步 ›', kind: 'primary', onClick: () => go(cur + 1) });
  // autoplay button with drawn play / pause icon
  const ax = 72 + ui.prev.w + ui.next.w + 20, aw = 132;
  const ag = el('g', { class: 'btn', transform: `translate(${ax},932)`, role: 'button' }, chrome);
  el('rect', { x: 0, y: 0, width: aw, height: 36, rx: 18 }, ag);
  ui.playIcon = el('path', { d: 'M20,11 L31,18 L20,25 Z', fill: C.ink }, ag);
  ui.pauseIcon = el('path', { d: 'M19,11 h4 v14 h-4 z M27,11 h4 v14 h-4 z', fill: C.ink, style: 'display:none' }, ag);
  ui.autoT = el('text', { x: 40, y: 23.4, 'font-size': 15, class: 'sans' }, ag, '自动播放');
  ag.addEventListener('click', (e) => { e.stopPropagation(); toggleAuto(); });
  ui.autoBtn = ag;
  // progress dots
  const n = scenes.length, gap = 22, x0 = 800 - ((n - 1) * gap) / 2;
  ui.dots = scenes.map((s, i) => {
    const dg = el('g', { class: 'dot' }, chrome);
    el('rect', { x: x0 + i * gap - 12, y: 936, width: 24, height: 24, fill: 'transparent' }, dg);
    const r = el('rect', { class: 'dr', x: x0 + i * gap - 4, y: 944, width: 8, height: 8, rx: 4 }, dg);
    dg.addEventListener('click', () => go(i));
    const tt = el('title', null, dg, i === 0 ? '封面' : `第 ${i} 步：${s.short}`);
    return { dg, r, cx: x0 + i * gap, tt };
  });
  ui.hint = label(chrome, 1440, 955, '', { size: 13, cls: 'sans ink3', anchor: 'end' });
  ui.page = label(chrome, 1528, 957, '', { size: 18, cls: 'mono', anchor: 'end', weight: 700 });
}

function updateChrome() {
  ui.prev.setDisabled(cur === 0);
  ui.next.setDisabled(cur === LAST);
  ui.dots.forEach((d, i) => {
    const on = i === cur;
    d.dg.classList.toggle('cur', on);
    d.r.setAttribute('width', on ? 22 : 8);
    d.r.setAttribute('x', d.cx - (on ? 11 : 4));
  });
  const sc = scenes[cur];
  ui.page.textContent = cur === 0 ? '封面' : `${cur} / ${LAST}`;
  ui.hint.textContent = '← → 翻页 · 空格 自动播放' + (sc.keys ? ' · ' + sc.keys : '');
}

function go(i, fromAuto) {
  i = clamp(i, 0, LAST);
  if (i === cur) return;
  if (!fromAuto && autoplay) stopAuto();
  const dir = i > cur ? 1 : -1;
  const prev = scenes[cur], next = scenes[i];
  if (prev) {
    if (prev.tl) prev.tl.kill();
    if (prev.leave) prev.leave();
    const pg = prev.g;
    pg.classList.remove('on', 'from-left', 'from-right');
    pg.classList.add(dir > 0 ? 'to-left' : 'to-right');
    setTimeout(() => { if (!pg.classList.contains('on')) pg.classList.remove('play'); }, 700);
  }
  const ng = next.g;
  ng.style.transition = 'none';
  ng.classList.remove('on', 'to-left', 'to-right', 'play');
  ng.classList.add(dir > 0 ? 'from-right' : 'from-left');
  void ng.getBoundingClientRect();
  ng.style.transition = '';
  ng.classList.remove('from-right', 'from-left');
  ng.classList.add('on', 'play');
  cur = i;
  next.tl = new Timeline();
  if (next.enter) next.enter(next.tl);
  updateChrome();
  if (autoplay) scheduleAuto();
}

function setAutoUI() {
  ui.playIcon.style.display = autoplay ? 'none' : '';
  ui.pauseIcon.style.display = autoplay ? '' : 'none';
  ui.autoT.textContent = autoplay ? '暂停播放' : '自动播放';
  ui.autoBtn.classList.toggle('on', false);
}
function scheduleAuto() {
  if (autoTL) autoTL.kill();
  autoTL = new Timeline();
  const sc = scenes[cur];
  const dwell = (sc.auto ? sc.auto(autoTL) : 0) || sc.dwell || 7000;
  autoTL.tween(dwell, (p) => ui.prog.setAttribute('x2', (72 + 1456 * p).toFixed(1)), EASE.lin);
  autoTL.at(dwell, () => { if (cur < LAST) go(cur + 1, true); else stopAuto(); });
}
function startAuto() {
  autoplay = true;
  setAutoUI();
  if (cur >= LAST) go(1, true); else scheduleAuto();
}
function stopAuto() {
  autoplay = false;
  if (autoTL) autoTL.kill();
  autoTL = null;
  ui.prog.setAttribute('x2', 72);
  setAutoUI();
}
function toggleAuto() { if (autoplay) stopAuto(); else startAuto(); }

document.addEventListener('keydown', (e) => {
  if (e.altKey || e.ctrlKey || e.metaKey) return;
  const k = e.key;
  if (k === 'ArrowRight' || k === 'PageDown') { go(cur + 1); e.preventDefault(); }
  else if (k === 'ArrowLeft' || k === 'PageUp') { go(cur - 1); e.preventDefault(); }
  else if (k === 'Home') { go(0); e.preventDefault(); }
  else if (k === 'End') { go(LAST); e.preventDefault(); }
  else if (k === ' ' || k === 'p' || k === 'P') { toggleAuto(); e.preventDefault(); }
  else if (k === 'Enter' && cur === 0) { go(1); e.preventDefault(); }
  else {
    const sc = scenes[cur];
    if (sc.key && sc.key(k)) { userAct(); e.preventDefault(); }
  }
});

buildChrome();
const startAt = parseInt(String(location.hash || '').replace(/[^0-9]/g, ''), 10);
go(Number.isFinite(startAt) ? clamp(startAt, 0, LAST) : 0);

// hooks for automated checks
window.__attn = {
  go: (i) => go(i),
  get cur() { return cur; },
  get autoplay() { return autoplay; },
  flush: () => { const s = scenes[cur]; if (s.tl) s.tl.flush(); if (s.freeze) s.freeze(); },
  scenes, state: ST, model: Model, params: PARAMS, tokens: TOK,
};

})();
